const RTGS=[{s:5,l:'Green',c:'ryg-green'},{s:4,l:'Green',c:'ryg-green'},{s:3,l:'Yellow',c:'ryg-yellow'},{s:2,l:'Red',c:'ryg-red'},{s:1,l:'Red',c:'ryg-red'}];
const FL={screen_print:'Screen print',embroidery:'Embroidery',art:'Art',shipping:'Shipping',vendor:'Vendor',rep:'Rep',customer:'Customer',other:'Other'};
const AET={color_type:'Color type',incomplete_art:'Incomplete art sheet',location:'Location',missing_info:'Missing information',order_entry:'Order entry',size:'Size'};
