const HR_CATS={tardy:{label:'Tardy',pts:.5,badge:'hr-tardy',note:'Tardy = 0.5 pts'},absence:{label:'Unexcused absence',pts:1,badge:'hr-absence',note:'Absence = 1 pt'},conduct:{label:'Conduct issue',pts:1,badge:'hr-conduct',note:'Conduct = 1 pt'},performance:{label:'Performance warning',pts:1,badge:'hr-perf',note:'Performance warning = 1 pt'},verbal:{label:'Verbal warning',pts:1,badge:'hr-verbal',note:'Verbal warning = 1 pt'},written:{label:'Written warning',pts:2,badge:'hr-written',note:'Written warning = 2 pts'},final:{label:'Final written warning',pts:3,badge:'hr-final',note:'Final warning = 3 pts'},pip:{label:'PIP',pts:5,badge:'hr-pip',note:'PIP = 5 pts'}};
