  {decoration:'Heat Transfer',shipWeek:'6/17/2026',updated:'Tue, Jun 9, 2026, 5:34 PM'},
  {decoration:'Screen Print',shipWeek:'6/16/2026',updated:'Tue, Jun 9, 2026, 5:34 PM'},
  {decoration:'Sublimation',shipWeek:'6/16/2026',updated:'Tue, Jun 9, 2026, 5:34 PM'},
  {decoration:'DTF (<500 Transfers)',shipWeek:'6/16/2026',updated:'Tue, Jun 16, 2026, 12:00 AM'},
  {decoration:'DTF (>500 Transfers)',shipWeek:'6/23/2026',updated:'Tue, Jun 9, 2026, 5:34 PM'}
