function ensureProductionKnowledge(){
  if(!S.companyKnowledge)S.companyKnowledge={categories:{},freeform:'',lastUpdated:null};
  if(!S.companyKnowledge.production)S.companyKnowledge.production={sheetUrl:'',rows:DEFAULT_PRODUCTION_ROWS.slice(),lastFetched:null};
  if(!Array.isArray(S.companyKnowledge.production.rows)||!S.companyKnowledge.production.rows.length){
    S.companyKnowledge.production.rows=DEFAULT_PRODUCTION_ROWS.slice();
  }
}

function parseProductionDate(v){
  if(!v)return null;
  var s=String(v).trim();
  var d=new Date(s);
  if(!isNaN(d.getTime()))return d;
  var m=s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{2,4})$/);
  if(m){
    var y=parseInt(m[3],10); if(y<100)y+=2000;
    return new Date(y,parseInt(m[1],10)-1,parseInt(m[2],10));
  }
  return null;
}

function fmtShortDate(d){
  if(!d)return '--';
  try{return d.toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});}catch(e){return d.toLocaleDateString();}
}

function leadDaysFromToday(shipWeek){
  var d=parseProductionDate(shipWeek);
  if(!d)return null;
  var today=new Date(); today.setHours(0,0,0,0);
  d.setHours(0,0,0,0);
  return Math.round((d-today)/86400000);
}

function productionStatusClass(days){
  if(days===null)return 'amber';
  if(days<=10)return 'green';
  if(days<=16)return 'amber';
  return 'red';
}

function productionStatusLabel(days){
  if(days===null)return 'Needs review';
  if(days<0)return 'Past due';
  if(days<=10)return 'Normal';
  if(days<=16)return 'Extended';
  return 'High risk';
}



function saveProductionSheetUrl(){
  ensureProductionKnowledge();
  var el=document.getElementById('productionSheetUrl');
  S.companyKnowledge.production.sheetUrl=el?el.value.trim():'';
  markDirty();
}

function useSampleProductionTimes(){
  ensureProductionKnowledge();
  S.companyKnowledge.production.rows=DEFAULT_PRODUCTION_ROWS.slice();
  S.companyKnowledge.production.lastFetched=Date.now();
  markDirty();
  renderProductionHub();
}

async function refreshProductionTimes(){
  ensureProductionKnowledge();
  var adminUrl='';try{adminUrl=((getProductionFeedSettings()||{}).url||'').trim();}catch(e){}
  var urlEl=document.getElementById('productionSheetUrl');
  var url=adminUrl||(urlEl&&urlEl.value.trim())||S.companyKnowledge.production.sheetUrl||'';
  if(!url){
    useSampleProductionTimes();
    var box=document.getElementById('knowledgeAnswerBox');
    if(box)box.textContent='No Google Sheet CSV URL is configured yet, so I loaded the sample production schedule. Set the published CSV link in Admin \u2192 Production Feed Manager, then click Refresh to pull live production times.';
    return;
  }
  try{
    var res=await fetch(url,{cache:'no-store'});
    if(!res.ok)throw new Error('HTTP '+res.status);
    var csv=await res.text();
    var rows=parseProductionCSV(csv);
    if(!rows.length)throw new Error('No production rows found');
    S.companyKnowledge.production.sheetUrl=url;
    S.companyKnowledge.production.rows=rows;
    S.companyKnowledge.production.lastFetched=Date.now();
    markDirty();
    renderProductionHub();
    var ans=document.getElementById('knowledgeAnswerBox');
    if(ans)ans.textContent='Production times refreshed from Google Sheet. '+rows.length+' decoration methods loaded into Company Knowledge and AI context.';
  }catch(err){
    var ans2=document.getElementById('knowledgeAnswerBox');
    if(ans2)ans2.textContent='Could not pull production times from the sheet: '+err.message+'. Check that the Google Sheet is published as CSV and available to anyone with the link.';
  }
}

function getProductionRows(){
  ensureProductionKnowledge();
  return (S.companyKnowledge.production.rows||[]).slice();
}

function renderProductionHub(){
  var page=document.getElementById('pg-cknow');
  if(!page)return;
  ensureProductionKnowledge();
  var prod=S.companyKnowledge.production;
  var url=document.getElementById('productionSheetUrl');
  if(url)url.value=prod.sheetUrl||'';
  var rows=getProductionRows();
  var tbody=document.getElementById('productionRows');
  if(tbody){
    tbody.innerHTML=rows.map(function(r){
      var days=leadDaysFromToday(r.shipWeek);
      var cls=productionStatusClass(days);
      var d=parseProductionDate(r.shipWeek);
      return '<tr><td><strong>'+esc(r.decoration)+'</strong></td><td>'+esc(fmtShortDate(d)||r.shipWeek)+'</td><td>'+(days===null?'--':days+' days')+'</td><td><span class="prod-status '+cls+'">'+productionStatusLabel(days)+'</span></td><td>'+esc(r.updated||'--')+'</td></tr>';
    }).join('') || '<tr><td colspan="5" style="text-align:center;color:#A8AFC3;">No production rows loaded yet.</td></tr>';
  }
  var daysList=rows.map(function(r){return leadDaysFromToday(r.shipWeek);}).filter(function(v){return typeof v==='number'&&!isNaN(v);});
  var avg=daysList.length?Math.round(daysList.reduce(function(a,b){return a+b;},0)/daysList.length):null;
  var longest=null;
  rows.forEach(function(r){var d=leadDaysFromToday(r.shipWeek); if(typeof d==='number'&&(longest===null||d>longest.days))longest={days:d,row:r};});
  setText('prodMetricTypes',rows.length);
  setText('prodMetricAvg',avg===null?'--':avg+'d');
  setText('prodMetricLongest',longest?longest.days+'d':'--');
  setText('prodMetricLongestSub',longest?longest.row.decoration:'Highest-risk decoration');
  setText('prodMetricUpdated',prod.lastFetched?fmtShortDate(new Date(prod.lastFetched)):'Saved');
  var badge=document.getElementById('prodSourceBadge');
  if(badge)badge.textContent=prod.sheetUrl?'Google Sheet source':'Saved snapshot';
  var rec=document.getElementById('productionRecommendations');
  if(rec)rec.innerHTML=buildProductionRecommendations(rows).map(function(x){return '<div class="rec-card '+x.tone+'">'+x.text+'</div>';}).join('');
  var sel=document.getElementById('cutoffDecoration');
  if(sel){
    var current=sel.value;
    sel.innerHTML=rows.map(function(r){return '<option value="'+escAttr(r.decoration)+'">'+esc(r.decoration)+'</option>';}).join('');
    if(current)sel.value=current;
  }
  renderKnowledgeRecentUpdates();
  renderContextHealth();
  calculateProductionCutoff();
}

function buildProductionRecommendations(rows){
  if(!rows.length)return [{tone:'amber',text:'No production data loaded yet. Paste a published Google Sheet CSV URL to turn this into a live production command center.'}];
  var out=[];
  var longest=null;
  rows.forEach(function(r){var d=leadDaysFromToday(r.shipWeek); if(typeof d==='number'&&(longest===null||d>longest.days))longest={days:d,row:r};});
  var quick=rows.filter(function(r){var d=leadDaysFromToday(r.shipWeek);return typeof d==='number'&&d<=10;}).map(function(r){return r.decoration;});
  if(quick.length)out.push({tone:'green',text:'Quick-turn opportunities: '+quick.slice(0,3).join(', ')+' are currently inside a roughly 10-day production window.'});
  if(longest)out.push({tone:longest.days>16?'red':'amber',text:'Longest lead time: '+longest.row.decoration+' is currently about '+longest.days+' days out. Quote this carefully and avoid overpromising.'});
  var emb=rows.filter(function(r){return /embroidery/i.test(r.decoration);});
  if(emb.length)out.push({tone:'amber',text:'Embroidery is visible in the production schedule. Use the ship week before promising decorated hats, polos, or name personalization.'});
  out.push({tone:'green',text:'Reports and AI summaries can reference this production snapshot so selling recommendations reflect current capacity.'});
  return out;
}

function calculateProductionCutoff(){
  var result=document.getElementById('cutoffResult');
  if(!result)return;
  var eventEl=document.getElementById('cutoffEventDate');
  var decEl=document.getElementById('cutoffDecoration');
  var eventDate=eventEl&&eventEl.value?new Date(eventEl.value+'T00:00:00'):null;
  var rows=getProductionRows();
  var row=rows.find(function(r){return decEl&&r.decoration===decEl.value;})||rows[0];
  result.className='cutoff-result';
  if(!eventDate||!row){result.textContent='Select a date and decoration to see production risk.';return;}
  var ship=parseProductionDate(row.shipWeek);
  if(!ship){result.textContent='This decoration does not have a readable ship week yet.';return;}
  ship.setHours(0,0,0,0);
  var diff=Math.round((eventDate-ship)/86400000);
  if(diff>=7){
    result.classList.add('good');
    result.textContent='Good window: '+row.decoration+' is showing a ship week of '+fmtShortDate(ship)+', about '+diff+' days before the event. This looks workable if order/art approvals are handled promptly.';
  }else if(diff>=0){
    result.classList.add('warn');
    result.textContent='Tight window: '+row.decoration+' is showing a ship week of '+fmtShortDate(ship)+', only '+diff+' days before the event. Treat this as risk-sensitive and confirm production before promising delivery.';
  }else{
    result.classList.add('bad');
    result.textContent='High risk: '+row.decoration+' is showing a ship week of '+fmtShortDate(ship)+', which is after the event date. Recommend a faster decoration method, stock items, or revised expectations.';
  }
}

function quickKnowledge(topic){
  var input=document.getElementById('knowledgeAskInput');
  var map={
    production:'What are the current production times?',
    rush:'What should I recommend for a rush order?',
    credit:'What is the credit memo policy?',
    art:'What are the art requirements?',
    pricing:'What pricing rules should reps remember?',
    returns:'What should reps know about returns or replacement orders?',
    'customer-care':'What customer care standards should reps follow?',
    remote:'What work standards and activity expectations should reps know?'
  };
  if(input)input.value=map[topic]||topic;
  askCompanyKnowledge();
}

function askCompanyKnowledge(){
  var q=(document.getElementById('knowledgeAskInput')||{}).value||'';
  var box=document.getElementById('knowledgeAnswerBox');
  if(!box)return;
  var lower=q.toLowerCase();
  var rows=getProductionRows();
  var prodSummary=rows.map(function(r){var d=leadDaysFromToday(r.shipWeek);return r.decoration+': '+(d===null?'ship week '+r.shipWeek:d+' days / ship week '+fmtShortDate(parseProductionDate(r.shipWeek)));}).join('\n');
  var answer='';
  if(lower.indexOf('production')>=0||lower.indexOf('ship')>=0||lower.indexOf('lead')>=0||lower.indexOf('rush')>=0){
    answer='Current production snapshot:\n'+prodSummary+'\n\nManager guidance: match the product/decorating method to the required event date. For anything tight, confirm production before promising delivery.';
  }else if(lower.indexOf('credit')>=0){
    answer='Credit memo guidance comes from your AI Command Library. Use credit memos to track fault, customer impact, rep coaching opportunities, and quality patterns. For rep-fault issues, tie the discussion back to order accuracy and preventable breakdowns.';
  }else if(lower.indexOf('art')>=0){
    answer='Art guidance comes from your Art & Production notes. Confirm usable artwork, approval status, decoration method, and production handoff before setting expectations. Art delays can change the real delivery window even when production capacity looks available.';
  }else if(lower.indexOf('price')>=0||lower.indexOf('pricing')>=0){
    answer='Pricing guidance comes from Products & Pricing plus free-form company notes. Keep recommendations tied to margin, decoration complexity, quantity, customer relationship, and realistic production capacity.';
  }else{
    answer='I can answer using the AI Command Library, free-form company notes, and live production snapshot. Try asking about current production, rush orders, credit memos, art requirements, or pricing rules.';
  }
  box.textContent=answer;
}

