function getProductionContext(){
  var rows=getProductionRows();
  if(!rows.length)return '';
  var lines=rows.map(function(r){
    var d=leadDaysFromToday(r.shipWeek);
    return '- '+r.decoration+': ship week '+fmtShortDate(parseProductionDate(r.shipWeek))+(d===null?'':' ('+d+' days from today)')+', status '+productionStatusLabel(d)+(r.updated?', updated '+r.updated:'');
  });
  return 'CURRENT PRODUCTION TIMES (use this when recommending products, rush options, forecast opportunities, and report commentary):\n'+lines.join('\n')+'\n\n---\n\n';
}

function setText(id,val){var el=document.getElementById(id);if(el)el.textContent=val;}
function esc(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
function escAttr(s){return esc(s).replace(/"/g,'&quot;');}

function getCompanyContext(){
  ensureProductionKnowledge();
  var ck=S.companyKnowledge;
  var parts=[];
  var prodCtx=getProductionContext();
  CKNOW_CATS.forEach(function(cat){
    var c=ck.categories&&ck.categories[cat.key];
    if(c&&c.content&&c.content.trim()){
      parts.push('## '+cat.title+'\n'+c.content.trim());
    }
  });
  if(ck.freeform&&ck.freeform.trim()){
    parts.push('## Additional Context\n'+ck.freeform.trim());
  }
  var companyBlock=parts.length?'COMPANY CONTEXT (how Triple Crown Products actually operates — use this to make your advice specific and accurate to this business, not generic sales coaching):\n\n'+parts.join('\n\n')+'\n\n---\n\n':'';
  return (prodCtx||'')+companyBlock;
}

function previewCompanyContext(){
  var ctx=getCompanyContext();
  if(!ctx){alert('No company context filled in yet. Fill in some categories first.');return;}
  var w=window.open('','_blank');
  if(!w){alert('Allow pop-ups.');return;}
  var html='<!DOCTYPE html><html><head><title>What AI sees</title><style>body{font-family:system-ui,sans-serif;max-width:780px;margin:30px auto;padding:0 20px;background:#fafafa;color:#222;line-height:1.6;}h1{color:#FA873D;font-size:20px;}pre{background:white;padding:18px;border-radius:8px;border:1px solid #ddd;white-space:pre-wrap;word-wrap:break-word;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:12.5px;line-height:1.5;}.meta{color:#888;font-size:12px;margin-bottom:14px;}</style></head><body><h1>\ud83e\udde0 What the AI receives as company context</h1><p class="meta">This block gets prepended to every AI prompt \u2014 meeting reports, rep performance reports, quarterly reviews, market intel. The AI uses this to make its suggestions specific to how Triple Crown Products actually works, instead of generic boilerplate.</p><pre>'+ctx.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')+'</pre></body></html>';
  w.document.write(html);
  w.document.close();
}

function exportCompanyKnowledge(){
  var ck=S.companyKnowledge||{categories:{},freeform:'',lastUpdated:null};
  var blob=new Blob([JSON.stringify(ck,null,2)],{type:'application/json'});
  var url=URL.createObjectURL(blob);
  var a=document.createElement('a');
  a.href=url;
  a.download='tcp_company_knowledge.json';
  a.click();
  setTimeout(function(){URL.revokeObjectURL(url);},100);
}

function importCompanyKnowledge(event){
  var f=event.target.files[0];
  if(!f)return;
  var r=new FileReader();
  r.onload=function(e){
    try{
      var data=JSON.parse(e.target.result);
      if(!data.categories&&!data.freeform)throw new Error('Invalid file');
      if(!confirm('Replace your current company knowledge with this file content?'))return;
      S.companyKnowledge=data;
      markDirty();
      renderCKnow();
    }catch(err){alert('Import failed: '+err.message);}
    event.target.value='';
  };
  r.readAsText(f);
}

function clearCompanyKnowledge(){
  if(!confirm('Wipe ALL company knowledge? This cannot be undone unless you have an export.'))return;
  S.companyKnowledge={categories:{},freeform:'',lastUpdated:null};
  markDirty();
  renderCKnow();
}

function startCKnowInterview(catKey){
  var cat=CKNOW_CATS.find(function(c){return c.key===catKey;});
  if(!cat)return;
  var apiKey=localStorage.getItem('claudeAPIKey');
  var qs=cat.questions;
  var existing=(S.companyKnowledge&&S.companyKnowledge.categories&&S.companyKnowledge.categories[catKey]&&S.companyKnowledge.categories[catKey].content)||'';
  var modal=document.getElementById('cknowInterviewModal');
  if(modal)modal.remove();
  modal=document.createElement('div');
  modal.id='cknowInterviewModal';
  modal.style.cssText='position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,.7);z-index:99999;display:flex;align-items:center;justify-content:center;padding:20px;';
  modal.innerHTML='<div style="background:var(--color-background-primary);max-width:760px;width:100%;max-height:85vh;overflow-y:auto;border-radius:10px;padding:22px 26px;border:0.5px solid var(--color-border-secondary);box-shadow:0 10px 40px rgba(0,0,0,.4);">'
    +'<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;">'
    +'<div><div style="font-size:17px;font-weight:600;">'+cat.icon+' '+cat.title+' interview</div><div style="font-size:11px;color:var(--color-text-secondary);margin-top:2px;">'+cat.desc+'</div></div>'
    +'<button onclick="document.getElementById(\'cknowInterviewModal\').remove()" style="background:transparent;border:none;color:var(--color-text-secondary);font-size:22px;cursor:pointer;line-height:1;">&times;</button>'
    +'</div>'
    +'<div style="background:var(--color-background-secondary);border-left:3px solid #FA873D;padding:9px 13px;border-radius:5px;font-size:11px;color:var(--color-text-primary);margin-bottom:14px;line-height:1.5;">Answer however much or little you want for each question. Skip anything that does not apply. When you click Save, your answers become this category\'s knowledge.'+(apiKey?' Since your API key is set, AI will also rewrite your answers into clean, structured notes.':' (No API key set \u2014 answers saved verbatim.)')+'</div>'
    +qs.map(function(q,i){return '<div style="margin-bottom:12px;"><div style="font-size:12px;font-weight:500;margin-bottom:4px;color:var(--color-text-primary);">'+(i+1)+'. '+q+'</div><textarea id="cknowAns_'+i+'" placeholder="Your answer..." style="width:100%;min-height:55px;padding:7px 10px;font-size:12px;border:0.5px solid var(--color-border-secondary);border-radius:var(--border-radius-md);background:var(--color-background-secondary);color:var(--color-text-primary);font-family:inherit;resize:vertical;"></textarea></div>';}).join('')
    +(existing?'<div style="margin-top:14px;padding-top:14px;border-top:0.5px solid var(--color-border-secondary);"><div style="font-size:11px;font-weight:600;color:var(--color-text-secondary);margin-bottom:6px;">Current saved notes (will be REPLACED unless you check Append):</div><div style="font-size:11px;color:var(--color-text-secondary);background:var(--color-background-secondary);padding:8px 10px;border-radius:5px;max-height:120px;overflow-y:auto;white-space:pre-wrap;font-family:ui-monospace,monospace;">'+existing.replace(/</g,'&lt;')+'</div><label style="font-size:11px;color:var(--color-text-secondary);margin-top:6px;display:inline-flex;align-items:center;gap:5px;cursor:pointer;"><input type="checkbox" id="cknowAppend"> Append to existing instead of replacing</label></div>':'')
    +'<div style="margin-top:16px;display:flex;gap:8px;justify-content:flex-end;">'
    +'<button onclick="document.getElementById(\'cknowInterviewModal\').remove()" style="padding:8px 16px;font-size:12px;border:0.5px solid var(--color-border-secondary);border-radius:6px;background:transparent;color:var(--color-text-primary);cursor:pointer;">Cancel</button>'
    +'<button id="cknowSubmitBtn" onclick="submitCKnowInterview(\''+catKey+'\')" style="padding:8px 18px;font-size:12px;border:none;border-radius:6px;background:#FA873D;color:white;cursor:pointer;font-weight:600;">'+(apiKey?'\u2713 Save (AI cleanup)':'\u2713 Save')+'</button>'
    +'</div></div>';
  document.body.appendChild(modal);
  setTimeout(function(){var el=document.getElementById('cknowAns_0');if(el)el.focus();},100);
}

async function submitCKnowInterview(catKey){
  var cat=CKNOW_CATS.find(function(c){return c.key===catKey;});
  if(!cat)return;
  var btn=document.getElementById('cknowSubmitBtn');
  if(btn){btn.disabled=true;btn.innerHTML='Saving...';}
  var pairs=cat.questions.map(function(q,i){
    var ans=(document.getElementById('cknowAns_'+i)||{}).value||'';
    return {q:q,a:ans.trim()};
  }).filter(function(p){return p.a.length>0;});
  if(!pairs.length){
    if(btn){btn.disabled=false;btn.innerHTML='\u2713 Save';}
    alert('No answers given. Nothing to save.');
    return;
  }
  var appendMode=document.getElementById('cknowAppend');
  appendMode=appendMode&&appendMode.checked;
  var apiKey=localStorage.getItem('claudeAPIKey');
  var result='';
  if(apiKey){
    var prompt='You are organizing notes about how a custom branded apparel company (Triple Crown Products, Mukwonago WI) operates. Below are interview Q&A about their "'+cat.title+'" practices.\n\nRewrite the answers into clean, structured notes (do NOT repeat the questions). Use short paragraphs or bullet points. Preserve every factual detail and specific term the user mentioned. Do NOT add anything they did not say. Do NOT use marketing-speak. Be concise. Output ONLY the cleaned notes, nothing else.\n\n';
    pairs.forEach(function(p){prompt+='Q: '+p.q+'\nA: '+p.a+'\n\n';});
    try{
      result=await callAI(prompt);
    }catch(e){
      console.warn('AI cleanup failed, saving raw:',e);
      result=pairs.map(function(p){return '**'+p.q+'**\n'+p.a;}).join('\n\n');
    }
  }else{
    result=pairs.map(function(p){return '**'+p.q+'**\n'+p.a;}).join('\n\n');
  }
  if(!S.companyKnowledge)S.companyKnowledge={categories:{},freeform:'',lastUpdated:null};
  if(appendMode){
    var existing=(S.companyKnowledge.categories[catKey]&&S.companyKnowledge.categories[catKey].content)||'';
    S.companyKnowledge.categories[catKey]={content:(existing+'\n\n'+result).trim()};
  }else{
    S.companyKnowledge.categories[catKey]={content:result};
  }
  S.companyKnowledge.lastUpdated=Date.now();
  markDirty();
  var modal=document.getElementById('cknowInterviewModal');
  if(modal)modal.remove();
  renderCKnow();
}

function renderGoals(){let el=document.getElementById('gTable'),yr=parseInt(document.getElementById('gYr')?.value)||getYr(),curQ=getQ();if(!S.reps.length){el.innerHTML='<p style="font-size:12px;color:var(--color-text-secondary);">No reps.</p>';return;}let html='<table class="goals-table"><thead><tr><th style="min-width:90px;">Rep</th><th style="min-width:80px;"></th>'+QTRS.map(q=>'<th class="'+(q===curQ?'active-qtr':'')+'" style="text-align:center;padding:6px 8px;">'+q+(q===curQ?' \u2605':'')+'</th>').join('')+'</tr><tr><th></th><th style="font-size:10px;color:var(--color-text-secondary);">Goal type</th>'+QTRS.map(q=>'<th class="'+(q===curQ?'active-qtr':'')+'" style="text-align:right;padding:4px 8px;font-size:10px;font-weight:400;color:var(--color-text-secondary);">($)</th>').join('')+'</tr></thead><tbody>';S.reps.forEach((r)=>{[{field:'rev',label:'Revenue/qtr ($)',step:100,parser:'parseInt'},{field:'hrs',label:'Hours/wk',step:0.5,parser:'parseFloat'},{field:'calls',label:'Calls/wk',step:1,parser:'parseInt'},{field:'setSize',label:'Customers in set',step:1,parser:'parseInt'}].forEach((f,fi)=>{html+='<tr'+(fi===0?' style="border-top:0.5px solid var(--color-border-secondary);"':'')+'>'; if(fi===0)html+='<td rowspan="4" style="font-weight:500;vertical-align:middle;padding:6px 8px;">'+r.name+'</td>';html+='<td style="font-size:11px;color:var(--color-text-secondary);padding:4px 8px;white-space:nowrap;">'+f.label+'</td>';QTRS.forEach(q=>{let g=getGoal(r.name,yr,q),isActive=q===curQ;html+='<td class="'+(isActive?'active-qtr':'')+'" style="text-align:right;padding:3px 6px;"><input type="number" class="goals-input" value="'+(g[f.field]||0)+'" min="0" step="'+f.step+'" oninput="setGoal(\''+r.name+'\','+yr+',\''+q+'\',\''+f.field+'\','+f.parser+'(this.value)||0)"></td>';});html+='</tr>';});});el.innerHTML=html+'</tbody></table>';}
function pencil(onclick){return '<button class="edit-pencil" onclick="'+onclick+'">✏</button>';}

function renderDash(){
var yr=getYr(),q=getQ(),weeks=gwq(yr,q),we=weeksElapsed(yr,q),cwk=getCWK();
var dr=activeReps().filter(function(r){var t=totW(r.name,weeks),hrP=getHRPoints(r.name,yr,q),ro=repGoalObj(r.name,yr,q);return calcSc(r.name,t,ro,weeks.length,hrP,we).fin<=2;}).length;
var wkAlerts=[];
S.reps.forEach(function(r){
  if(dateInCurrentWeek(r.profile&&r.profile.hireDate)){var y=yearsAgo(r.profile.hireDate);wkAlerts.push({id:"anniv_"+r.name+"_"+cwk,type:"anniv",html:"<strong>"+r.name+"</strong> — "+y+"-year anniversary!",cls:"alert-anniv",icon:"&#127881;"});}
  if(dateInCurrentWeek(r.profile&&r.profile.birthday)){wkAlerts.push({id:"bday_"+r.name+"_"+cwk,type:"bday",html:"<strong>"+r.name+"</strong>'s birthday!",cls:"alert-bday",icon:"&#127874;"});}
  var rec=checkNewRecords(r.name,cwk);
  if(rec.newWeekRecord)wkAlerts.push({id:"rec_wk_"+r.name+"_"+cwk,type:"record",html:"<strong>"+r.name+"</strong> — new best week!",cls:"alert-record",icon:"&#127942;"});
  if(rec.newSaleRecord)wkAlerts.push({id:"rec_sl_"+r.name+"_"+cwk,type:"record",html:"<strong>"+r.name+"</strong> — new top sale!",cls:"alert-record",icon:"&#11088;"});
});
var _lastWk=null;weeks.forEach(function(w){if(activeReps().some(function(r){var d=gd(r.name+'|'+w.key);return (d.revenue||d.calls||d.hours||d.orders||d.acctsCalled);}))_lastWk=w;});
activeReps().forEach(function(r){
var _t=totW(r.name,weeks);
var _cov=_t.setSize>0?Math.round(_t.acctsCalled/_t.setSize*100):-1;
if(_cov>=0&&_cov<60)wkAlerts.push({id:"cov_"+r.name+"_"+cwk,type:"cov_gap",html:"<strong>"+r.name+"</strong> &#8212; only "+_cov+"% of customers reached ("+Math.round(_t.acctsCalled).toLocaleString()+" / "+Math.round(_t.setSize).toLocaleString()+")",cls:"alert-action",icon:"&#128202;"});
if(_t.art>=12)wkAlerts.push({id:"art_"+r.name+"_"+cwk,type:"art_spike",html:"<strong>"+r.name+"</strong> &#8212; "+_t.art+" art errors this quarter",cls:"alert-action",icon:"&#127912;"});
if(_t.credits>=1000)wkAlerts.push({id:"cred_"+r.name+"_"+cwk,type:"cred_spike",html:"<strong>"+r.name+"</strong> &#8212; $"+Math.round(_t.credits).toLocaleString()+" in rep-fault credits",cls:"alert-action",icon:"&#128184;"});
if(_lastWk){var _dd=gd(r.name+'|'+_lastWk.key);var _has=(_dd.revenue||_dd.calls||_dd.hours||_dd.orders||_dd.acctsCalled);var _act=weeks.some(function(w){var _d2=gd(r.name+'|'+w.key);return (_d2.revenue||_d2.calls||_d2.hours||_d2.orders||_d2.acctsCalled);});if(!_has&&_act)wkAlerts.push({id:"miss_"+r.name+"_"+_lastWk.key,type:"missing",html:"<strong>"+r.name+"</strong> &#8212; no scorecard entered for "+_lastWk.label,cls:"alert-action",icon:"&#128221;"});}
});
var allA=[];
if(dr>0)allA.push({id:"risk_"+cwk,type:"risk",html:"<strong>"+dr+" rep"+(dr>1?"s":"")+"</strong> rated Not Meeting or below",cls:"alert-warn",icon:"&#9888;&#65039;"});
wkAlerts.forEach(function(a){allA.push(a);});
allA.forEach(function(a){if(!notifLog.find(function(n){return n.id===a.id;})){notifLog.unshift({id:a.id,type:a.type,html:a.html,cls:a.cls,icon:a.icon,week:cwk,ts:new Date().toLocaleString("en-US",{month:"short",day:"numeric",hour:"numeric",minute:"2-digit"})});}});
updateNotifBadge();
var visA=allA.filter(function(a){return!dismissedAlerts.has(a.id);});
var aHtml=visA.length>1?"<div style='display:flex;justify-content:flex-end;margin-bottom:4px;'><button onclick='dismissAllAlerts()' style='font-size:10px;padding:2px 8px;border:0.5px solid var(--color-border-secondary);border-radius:4px;background:var(--color-background-secondary);color:var(--color-text-secondary);cursor:pointer;'>× Dismiss all</button></div>":"";
aHtml+=visA.map(function(a){return'<div class="alert-banner '+a.cls+'" style="justify-content:space-between;"><span>'+a.icon+" "+a.html+"</span><button data-nid='"+a.id+"' onclick='dismissAlert(this.dataset.nid)' style='font-size:10px;padding:1px 6px;border:0.5px solid currentColor;border-radius:4px;background:none;color:inherit;cursor:pointer;'>×</button></div>";}).join("");
document.getElementById("dAlerts").innerHTML=aHtml;
renderDashWidgets();
}

function renderRL(){let el=document.getElementById('rList');if(!S.reps.length){el.innerHTML='<p style="font-size:12px;color:var(--color-text-secondary);">No reps.</p>';return;}el.innerHTML=S.reps.map((r,i)=>{let isRetired=!!r.retired;return'<div class="ri" id="ri'+i+'" style="'+(isRetired?'opacity:.6;':'')+'"><div style="display:flex;align-items:center;gap:7px;flex:1;">'+avHtml(r.name,i,{})+'<div class="editable-row" id="rname_row_'+i+'"><span style="font-size:12px;font-weight:500;'+(isRetired?'text-decoration:line-through;color:var(--color-text-secondary);':'')+'">'+r.name+'</span>'+(isRetired?'<span style="font-size:10px;padding:1px 5px;border-radius:8px;background:#2A2936;color:#8B8A94;margin-left:4px;">Retired</span>':pencil('editRepName('+i+')'))+'</div></div><div id="ra'+i+'" style="display:flex;gap:5px;">'+(isRetired?'<button class="sbtn" style="font-size:11px;padding:3px 8px;" onclick="toggleRetire('+i+')">&#8617; Restore</button>':'<button class="sbtn" style="font-size:11px;padding:3px 8px;color:#EF9F27;border-color:#EF9F27;" onclick="toggleRetire('+i+')">&#128679; Retire</button><button class="rbtn" onclick="askRm('+i+')">Remove</button>')+'</div></div>';}).join('');}
function editRepName(i){let cid='rname_row_'+i,oldName=S.reps[i].name;document.querySelectorAll('.inline-edit-box').forEach(el=>el.remove());let row=document.getElementById(cid);if(!row)return;let box=document.createElement('div');box.className='inline-edit-box';box.id='iebox_rn_'+i;box.innerHTML='<div class="ig" style="flex:1;"><label>Edit name</label><input id="ie_rname_'+i+'" type="text" value="'+oldName+'" style="min-width:160px;"></div><div style="display:flex;gap:6px;margin-top:4px;width:100%;"><button class="ie-save" onclick="saveRepName('+i+')">✓ Save</button><button class="ie-cancel" onclick="document.getElementById(\'iebox_rn_'+i+'\')?.remove()">Cancel</button></div>';row.appendChild(box);setTimeout(()=>{let inp=document.getElementById('ie_rname_'+i);if(inp){inp.focus();inp.select();}},50);}
function saveRepName(i){let inp=document.getElementById('ie_rname_'+i);if(!inp)return;let newName=inp.value.trim();if(!newName)return;let oldName=S.reps[i].name;migratePhotoKey(oldName,newName);Object.keys(S.data).filter(k=>k.startsWith(oldName+'|')).forEach(k=>{S.data[newName+'|'+k.slice(oldName.length+1)]=S.data[k];delete S.data[k];});if(S.goals[oldName]){S.goals[newName]=S.goals[oldName];delete S.goals[oldName];}S.cms.forEach(c=>{if(c.rep===oldName)c.rep=newName;});S.artErrors.forEach(a=>{if(a.rep===oldName)a.rep=newName;});S.hrViolations.forEach(v=>{if(v.rep===oldName)v.rep=newName;});S.coachingNotes.forEach(n=>{if(n.rep===oldName)n.rep=newName;});if(selectedRep===oldName)selectedRep=newName;S.reps[i].name=newName;document.getElementById('iebox_rn_'+i)?.remove();markDirty();popSel();renderRL();renderGoals();renderProfileCards();markDirty();}
function askRm(i){document.getElementById('ra'+i).innerHTML='<div style="display:flex;align-items:center;gap:5px;"><span style="font-size:11px;color:#791F1F;">Remove '+S.reps[i].name+'?</span><button class="cbtn-y" onclick="doRm('+i+')">Yes</button><button class="cbtn-n" onclick="renderRL()">No</button></div>';}
function doRm(i){let name=S.reps[i].name;S.reps.splice(i,1);if(selectedRep===name)selectedRep=S.reps[0]?.name||null;markDirty();popSel();renderRL();renderGoals();}
function addRep(){let n=document.getElementById('nR').value.trim();if(!n||S.reps.find(r=>r.name===n))return;S.reps.push({name:n,retired:false,profile:{photo:null,hireDate:'',birthday:'',favFood:'',favCandy:'',favDrink:'',starbucks:'',favMovie:'',favBook:'',manualBestWeek:0,manualBestWeekLabel:'',manualBestSale:0,manualRevBaseline:0}});document.getElementById('nR').value='';popSel();renderRL();renderGoals();}

function avatarEl(r,i,sz){sz=sz||50;var nameAttr=(r&&r.name?r.name.replace(/'/g,"\\'"):'');if(r.profile?.photo)return'<img src="'+r.profile.photo+'" style="width:'+sz+'px;height:'+sz+'px;border-radius:50%;object-fit:cover;cursor:pointer;flex-shrink:0;" onclick="triggerPhoto(\''+nameAttr+'\')" title="Click to replace photo">';let fs=Math.round(sz*0.32);return'<div style="width:'+sz+'px;height:'+sz+'px;border-radius:50%;background:'+AV_BG[i%AV_BG.length]+';color:'+AV_FG[i%AV_FG.length]+';display:flex;align-items:center;justify-content:center;font-size:'+fs+'px;font-weight:500;cursor:pointer;flex-shrink:0;" onclick="triggerPhoto(\''+nameAttr+'\')" title="Click to upload photo">'+r.name.split(' ').map(x=>x[0]).join('')+'</div>';}
function triggerPhoto(repRef){var ri=typeof repRef==='number'?repRef:S.reps.findIndex(function(r){return r&&r.name===repRef;});if(ri<0||!S.reps[ri])return;var targetName=S.reps[ri].name;var inp=document.createElement('input');inp.type='file';inp.accept='image/*';inp.onchange=function(e){var f=e.target.files[0];if(!f)return;var rd=new FileReader();rd.onload=function(ev){var ri2=S.reps.findIndex(function(r){return r&&r.name===targetName;});if(ri2<0)return;if(!S.reps[ri2].profile)S.reps[ri2].profile={};S.reps[ri2].profile.photo=ev.target.result;persistPhoto(targetName,ev.target.result);renderProfileCards();if(selectedRep===targetName)renderProfileDetail(ri2);};rd.readAsDataURL(f);};inp.click();}
function clearPhoto(repName){if(!repName)return;if(!confirm('Remove '+repName+'&apos;s photo? Their avatar will go back to initials.'.replace('&apos;','\''))) return;var ri=S.reps.findIndex(function(r){return r&&r.name===repName;});if(ri<0)return;if(S.reps[ri].profile)S.reps[ri].profile.photo=null;persistPhoto(repName,null);renderProfileCards();if(selectedRep===repName)renderProfileDetail(ri);if(typeof renderDashWidgets==='function')renderDashWidgets();if(typeof renderLB==='function')renderLB();}
var _dismissedProfileAlerts=new Set(JSON.parse(localStorage.getItem('dismissedProfileAlerts')||'[]'));
function renderProfileAlerts(){
  var items=[],cwk=getCWK();
  S.reps.forEach(function(r){
    if(dateInCurrentWeek(r.profile&&r.profile.hireDate)){var y=yearsAgo(r.profile.hireDate);items.push({id:'anniv_'+r.name+'_'+cwk,cls:'alert-anniv',icon:'&#127881;',html:'<strong>'+r.name+'</strong> — '+y+'-year anniversary!',});}
    if(dateInCurrentWeek(r.profile&&r.profile.birthday)){items.push({id:'bday_'+r.name+'_'+cwk,cls:'alert-bday',icon:'&#127874;',html:'<strong>'+r.name+'</strong>\'s birthday!',});}
    var rec=checkNewRecords(r.name,cwk);
    if(rec.newWeekRecord)items.push({id:'rec_wk_'+r.name+'_'+cwk,cls:'alert-record',icon:'&#127942;',html:'<strong>'+r.name+'</strong> — new best week!'});
    if(rec.newSaleRecord)items.push({id:'rec_sl_'+r.name+'_'+cwk,cls:'alert-record',icon:'&#11088;',html:'<strong>'+r.name+'</strong> — new top sale!'});
  });
  var visible=items.filter(function(a){return!_dismissedProfileAlerts.has(a.id);});
  var html='';
  if(items.length>1&&visible.length>1){
    html+='<div style="display:flex;justify-content:flex-end;margin-bottom:4px;">';
    html+='<button onclick="_dismissAllProfileAlerts()" style="font-size:10px;padding:2px 8px;border:0.5px solid var(--color-border-secondary);border-radius:4px;background:var(--color-background-secondary);color:var(--color-text-secondary);cursor:pointer;">× Dismiss all</button>';
    html+='</div>';
  }
  visible.forEach(function(a){
    html+='<div class="alert-banner '+a.cls+'" style="justify-content:space-between;align-items:center;">';
    html+='<span>'+a.icon+' '+a.html+'</span>';
    html+='<button data-pid="'+a.id+'" onclick="_dismissProfileAlert(this.dataset.pid)" style="font-size:11px;padding:1px 7px;border:0.5px solid currentColor;border-radius:4px;background:none;color:inherit;cursor:pointer;opacity:.7;flex-shrink:0;">×</button>';
    html+='</div>';
  });
  document.getElementById('profileAlerts').innerHTML=html;
}
function _dismissProfileAlert(id){
  _dismissedProfileAlerts.add(id);
  try{localStorage.setItem('dismissedProfileAlerts',JSON.stringify([..._dismissedProfileAlerts]));}catch(e){}
  renderProfileAlerts();
}
function _dismissAllProfileAlerts(){
  var cwk=getCWK();
  S.reps.forEach(function(r){
    _dismissedProfileAlerts.add('anniv_'+r.name+'_'+cwk);
    _dismissedProfileAlerts.add('bday_'+r.name+'_'+cwk);
    _dismissedProfileAlerts.add('rec_wk_'+r.name+'_'+cwk);
    _dismissedProfileAlerts.add('rec_sl_'+r.name+'_'+cwk);
  });
  try{localStorage.setItem('dismissedProfileAlerts',JSON.stringify([..._dismissedProfileAlerts]));}catch(e){}
  renderProfileAlerts();
}
function renderProfiles(){renderProfileAlerts();renderProfileCards();let ri=S.reps.findIndex(r=>r.name===selectedRep);if(ri>=0)renderProfileDetail(ri);}
function selectRep(name){selectedRep=name;renderProfileCards();let ri=S.reps.findIndex(r=>r.name===name);if(ri>=0)renderProfileDetail(ri);}

function saveHR(){let rep=document.getElementById('hrRep').value,date=document.getElementById('hrDate').value,cat=document.getElementById('hrCat').value,pts=parseFloat(document.getElementById('hrPts').value)||HR_CATS[cat]?.pts||0,week=document.getElementById('hrWeek').value,desc=document.getElementById('hrDesc').value.trim();if(!date){alert('Please enter a date.');return;}let yr=new Date(date+'T12:00:00').getFullYear(),q=dateToQ(date,yr)||getQ();S.hrViolations.push({id:Date.now(),rep,date,yr,q,cat,pts,week,desc});document.getElementById('hrDate').value='';document.getElementById('hrDesc').value='';let m=document.getElementById('hrMsg');m.style.display='inline';setTimeout(()=>m.style.display='none',2000);renderHRL();renderHRSummaryByRep();markDirty();}
function deleteHR(id){S.hrViolations=S.hrViolations.filter(v=>v.id!==id);renderHRL();renderHRSummaryByRep();markDirty();}
function renderHRL(){let fr=document.getElementById('hrFR')?.value||'all',fc=document.getElementById('hrFC')?.value||'all',fyr=document.getElementById('hrFYr')?.value||'all';let f=S.hrViolations.filter(v=>(fr==='all'||v.rep===fr)&&(fc==='all'||v.cat===fc)&&(fyr==='all'||v.yr==fyr));let totPts=f.reduce((s,v)=>s+v.pts,0);document.getElementById('hrSum').innerHTML=f.length?'<div class="chip"><div class="cv">'+f.length+'</div><div class="cl">violations</div></div><div class="chip" style="border-left:3px solid #E24B4A;"><div class="cv" style="color:#E24B4A;">'+totPts.toFixed(1)+'</div><div class="cl">HR pts</div></div>':'';let el=document.getElementById('hrLog');if(!f.length){el.innerHTML='<p style="font-size:12px;color:var(--color-text-secondary);padding:.4rem 0;">No violations found.</p>';return;}el.innerHTML=f.slice().reverse().map(v=>{let hc=HR_CATS[v.cat];return'<div class="log-row" id="hr_row_'+v.id+'"><div class="editable-row"><div style="flex:1;"><div style="display:flex;align-items:center;gap:7px;flex-wrap:wrap;margin-bottom:3px;"><span style="font-size:12px;font-weight:500;">'+v.rep+'</span><span class="'+(hc?.badge||'fault-other')+'">'+(hc?.label||v.cat)+'</span><span style="font-size:11px;color:var(--color-text-secondary);">'+fdfull(v.date)+'</span><span style="font-size:11px;font-weight:500;color:#E24B4A;">'+v.pts+' pts</span></div>'+(v.desc?'<div style="font-size:12px;color:var(--color-text-secondary);">'+v.desc+'</div>':'')+'</div><div style="display:flex;gap:5px;flex-shrink:0;">'+pencil('editHR('+v.id+')')+'<button class="rbtn" onclick="deleteHR('+v.id+')" style="font-size:10px;padding:2px 5px;">✕</button></div></div><div id="hr_edit_'+v.id+'"></div></div>';}).join('');}
function editHR(id){let v=S.hrViolations.find(x=>x.id===id);if(!v)return;document.querySelectorAll('.inline-edit-box').forEach(el=>el.remove());let box=document.getElementById('hr_edit_'+id);if(!box)return;let catOpts=Object.entries(HR_CATS).map(([k,h])=>'<option value="'+k+'"'+(v.cat===k?' selected':'')+'>'+h.label+'</option>').join('');box.innerHTML='<div class="inline-edit-box"><div class="ig"><label>Rep</label><select id="hie_rep_'+id+'">'+S.reps.map(r=>'<option'+(v.rep===r.name?' selected':'')+'>'+r.name+'</option>').join('')+'</select></div><div class="ig"><label>Date</label><input id="hie_date_'+id+'" type="date" value="'+v.date+'"></div><div class="ig"><label>Category</label><select id="hie_cat_'+id+'">'+catOpts+'</select></div><div class="ig"><label>Points</label><input id="hie_pts_'+id+'" type="number" value="'+v.pts+'" min="0" max="10" style="width:60px;"></div><div class="ig" style="flex:1;min-width:200px;"><label>Description</label><textarea id="hie_desc_'+id+'">'+(v.desc||'')+'</textarea></div><div style="display:flex;gap:6px;width:100%;margin-top:4px;"><button class="ie-save" onclick="saveHREdit('+id+')">✓ Save</button><button class="ie-cancel" onclick="document.getElementById(\'hr_edit_'+id+'\').innerHTML=\'\'">Cancel</button></div></div>';}
function saveHREdit(id){let v=S.hrViolations.find(x=>x.id===id);if(!v)return;v.rep=document.getElementById('hie_rep_'+id)?.value||v.rep;v.date=document.getElementById('hie_date_'+id)?.value||v.date;v.cat=document.getElementById('hie_cat_'+id)?.value||v.cat;v.pts=parseFloat(document.getElementById('hie_pts_'+id)?.value)||v.pts;v.desc=document.getElementById('hie_desc_'+id)?.value||'';v.yr=new Date(v.date+'T12:00:00').getFullYear();v.q=dateToQ(v.date,v.yr)||v.q;renderHRL();renderHRSummaryByRep();}
function saveCN(){let rep=document.getElementById('cnRep').value,date=document.getElementById('cnDate').value,type=document.getElementById('cnType').value,week=document.getElementById('cnWeek').value,note=document.getElementById('cnNote').value.trim();if(!note||!date){alert('Please enter a date and note.');return;}let yr=new Date(date+'T12:00:00').getFullYear(),q=dateToQ(date,yr)||getQ();S.coachingNotes.push({id:Date.now(),rep,date,yr,q,type,week,note});document.getElementById('cnDate').value='';document.getElementById('cnNote').value='';let m=document.getElementById('cnMsg');m.style.display='inline';setTimeout(()=>m.style.display='none',2000);renderCNL();markDirty();}
function _cnUpdatePlaceholder(){var t=(document.getElementById('cnType')||{}).value;var ta=document.getElementById('cnNote');if(!ta)return;var hints={coaching:'What was discussed...',positive:'What they did well...',concern:'What the concern is...',warning:'What was discussed...',pip:'Progress / check-in notes...',observation:'What you observed (no action needed, just logging it)...',latecallin:'e.g. Called in sick / arrived 25 min late / left early — time + reason if known'};ta.placeholder=hints[t]||'Details...';}
function deleteCN(id){S.coachingNotes=S.coachingNotes.filter(n=>n.id!==id);renderCNL();markDirty();}
function renderCNL(){let fr=document.getElementById('cnFR')?.value||'all',ft=document.getElementById('cnFT')?.value||'all',fyr=document.getElementById('cnFYr')?.value||'all';let f=S.coachingNotes.filter(n=>(fr==='all'||n.rep===fr)&&(ft==='all'||n.type===ft)&&(fyr==='all'||n.yr==fyr));let el=document.getElementById('cnLog');if(!f.length){el.innerHTML='<p style="font-size:12px;color:var(--color-text-secondary);padding:.4rem 0;">No notes found.</p>';return;}el.innerHTML=f.slice().reverse().map(n=>'<div class="note-card type-'+n.type+'" id="cn_row_'+n.id+'"><div class="editable-row" style="align-items:flex-start;"><div style="flex:1;"><div class="note-meta"><span style="font-size:12px;font-weight:500;">'+n.rep+'</span><span class="note-type-badge '+(CN_BADGES[n.type]||'ntb-coaching')+'">'+(CN_TYPES[n.type]||n.type)+'</span><span class="note-date">'+fdfull(n.date)+'</span></div><div class="note-text">'+n.note+'</div></div><div style="display:flex;gap:5px;flex-shrink:0;margin-left:8px;">'+pencil('editCN('+n.id+')')+'<button class="rbtn" onclick="deleteCN('+n.id+')" style="font-size:10px;padding:2px 5px;">✕</button></div></div><div id="cn_edit_'+n.id+'"></div></div>').join('');}
function editCN(id){let n=S.coachingNotes.find(x=>x.id===id);if(!n)return;document.querySelectorAll('.inline-edit-box').forEach(el=>el.remove());let box=document.getElementById('cn_edit_'+id);if(!box)return;let typeOpts=Object.entries(CN_TYPES).map(([k,l])=>'<option value="'+k+'"'+(n.type===k?' selected':'')+'>'+l+'</option>').join('');box.innerHTML='<div class="inline-edit-box"><div class="ig"><label>Rep</label><select id="cnie_rep_'+id+'">'+S.reps.map(r=>'<option'+(n.rep===r.name?' selected':'')+'>'+r.name+'</option>').join('')+'</select></div><div class="ig"><label>Date</label><input id="cnie_date_'+id+'" type="date" value="'+n.date+'"></div><div class="ig"><label>Type</label><select id="cnie_type_'+id+'">'+typeOpts+'</select></div><div class="ig" style="flex:1;min-width:220px;"><label>Note</label><textarea id="cnie_note_'+id+'">'+n.note+'</textarea></div><div style="display:flex;gap:6px;width:100%;margin-top:4px;"><button class="ie-save" onclick="saveCNEdit('+id+')">✓ Save</button><button class="ie-cancel" onclick="document.getElementById(\'cn_edit_'+id+'\').innerHTML=\'\'">Cancel</button></div></div>';}
function saveCNEdit(id){let n=S.coachingNotes.find(x=>x.id===id);if(!n)return;n.rep=document.getElementById('cnie_rep_'+id)?.value||n.rep;n.date=document.getElementById('cnie_date_'+id)?.value||n.date;n.type=document.getElementById('cnie_type_'+id)?.value||n.type;n.note=document.getElementById('cnie_note_'+id)?.value||n.note;n.yr=new Date(n.date+'T12:00:00').getFullYear();n.q=dateToQ(n.date,n.yr)||n.q;renderCNL();}
function renderHRSummaryByRep(){let yr=getYr(),q=getQ();let el=document.getElementById('hrSummaryByRep');let rows=activeReps().map(r=>{let qPts=getHRPoints(r.name,yr,q),ytdPts=S.hrViolations.filter(v=>v.rep===r.name&&v.yr==yr).reduce((s,v)=>s+v.pts,0);let hasPIP=S.hrViolations.some(v=>v.rep===r.name&&v.yr==yr&&v.cat==='pip'),hasFinal=S.hrViolations.some(v=>v.rep===r.name&&v.yr==yr&&v.cat==='final');let noteCount=S.coachingNotes.filter(n=>n.rep===r.name&&n.yr==yr&&n.q===q).length,cap=hrcap(qPts);return{name:r.name,qPts,ytdPts,hasPIP,hasFinal,noteCount,cap};});el.innerHTML='<div style="display:grid;grid-template-columns:1fr 65px 65px 65px 85px 70px;gap:5px;padding:4px 0;border-bottom:0.5px solid var(--color-border-secondary);font-size:11px;font-weight:500;color:var(--color-text-secondary);"><span>Rep</span><span>'+q+' pts</span><span>'+getYr()+' YTD</span><span>Notes</span><span>Rating cap</span><span>Status</span></div>'+rows.map(r=>{let capRt=rfrom(r.cap),status=r.hasPIP?'<span class="hr-pip">PIP</span>':r.hasFinal?'<span class="hr-final">Final</span>':r.qPts>=3?'<span class="hr-written">Warning</span>':r.qPts>0?'<span class="hr-tardy">Minor</span>':'<span style="font-size:11px;color:#5DCAA5;">Clean</span>';return'<div style="display:grid;grid-template-columns:1fr 65px 65px 65px 85px 70px;gap:5px;padding:8px 0;border-bottom:0.5px solid var(--color-border-tertiary);font-size:12px;align-items:center;"><span style="font-weight:500;">'+r.name+'</span><span style="color:'+(r.qPts>=3?'#E24B4A':r.qPts>0?'#EF9F27':'#5DCAA5')+';font-weight:500;">'+r.qPts.toFixed(1)+'</span><span>'+r.ytdPts.toFixed(1)+'</span><span>'+r.noteCount+'</span><span class="rb '+capRt.c+'" style="font-size:10px;padding:2px 5px;">'+capRt.l+'</span><span>'+status+'</span></div>';}).join('');}

function saveCM(){let rep=document.getElementById('cmRep').value,wk=document.getElementById('cmWeek').value,amt=parseFloat(document.getElementById('cmAmt').value)||0,fault=(document.getElementById('cmFault').value||'').toLowerCase(),custId=document.getElementById('cmCustId').value.trim(),custName=document.getElementById('cmCustName').value.trim(),soNum=document.getElementById('cmSO').value.trim(),invNum=document.getElementById('cmInv').value.trim(),desc=document.getElementById('cmDesc').value.trim();if(!amt)return;if(soNum||invNum){var _cmDup=(S.cms||[]).some(function(c){return c&&String(c.soNum||'').trim()===soNum&&String(c.invNum||'').trim()===invNum&&Math.round((Number(c.amount)||0)*100)===Math.round(amt*100);});if(_cmDup&&!confirm('You are adding a duplicate credit memo\n\n\u2022 SO #: '+(soNum||'\u2014')+'\n\u2022 Invoice #: '+(invNum||'\u2014')+'\n\u2022 Amount: $'+amt.toFixed(2)+'\n\nThis exact credit memo already exists. Do you still wish to proceed?'))return;}let parts=wk.split('_');S.cms.push({id:Date.now(),rep,weekKey:wk,yr:parts[0],q:parts[1],amount:amt,fault,custId,custName,soNum,invNum,desc,date:new Date().toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})});['cmAmt','cmCustId','cmCustName','cmSO','cmInv','cmDesc'].forEach(id=>document.getElementById(id).value='');document.getElementById('cmFault').value='screen_print';updateFN();let m=document.getElementById('cmMsg');m.style.display='inline';setTimeout(()=>m.style.display='none',2000);markDirty();renderCML();}
function deleteCM(id){S.cms=S.cms.filter(c=>c.id!==id);renderCML();markDirty();}
function faultBadge(fault){if(fault==='rep')return'<span class="fault-rep">Rep</span>';if(fault==='customer')return'<span class="fault-cust">Customer</span>';return'<span class="fault-other">'+(FL[fault]||fault)+'</span>';}
function _cmMoney(n){n=Number(n)||0;return '$'+n.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});}
function _cmSetText(id,txt){var el=document.getElementById(id);if(el)el.textContent=txt;}
function _cmSetHtml(id,html){var el=document.getElementById(id);if(el)el.innerHTML=html;}
function _cmNormalize(){
  if(!S.cms)S.cms=[];
  S.cms.forEach(function(c){
    if(!c.id)c.id=Date.now()+Math.floor(Math.random()*100000);
    c.amount=Number(c.amount||c.amt||c.total||0)||0;
    c.fault=(c.fault||'other').toString().toLowerCase();
    if(c.fault==='rep fault')c.fault='rep';
    if(c.fault==='customer fault')c.fault='customer';
    if(!c.weekKey&&c.week)c.weekKey=c.week;
    if(c.weekKey){var parts=String(c.weekKey).split('_');if(parts.length>=2){c.yr=c.yr||parts[0];c.q=c.q||parts[1];}}
    c.yr=String(c.yr||getYr());
    c.q=c.q||getQ();
    c.rep=c.rep||'';
  });
}
function _cmCurrentWeekKey(){try{if(typeof gwq!=='function')return '';var d=new Date();var wks=gwq(getYr(),getQ())||[];for(var i=0;i<wks.length;i++){var w=wks[i];if(w.start&&w.end&&d>=new Date(w.start)&&d<=new Date(new Date(w.end).getTime()+86399000))return w.key;}return wks.length?wks[wks.length-1].key:'';}catch(e){return '';}}
function _cmPopMWeek(){try{if(typeof gwq!=='function')return;var yrEl=document.getElementById('cmFYr'),qEl=document.getElementById('cmFQ'),mEl=document.getElementById('cmFM'),wEl=document.getElementById('cmFW');if(!mEl||!wEl)return;var yr=(yrEl&&yrEl.value&&yrEl.value!=='all')?Number(yrEl.value):getYr();var qs=(qEl&&qEl.value!=='all')?[qEl.value]:['Q1','Q2','Q3','Q4'];var months=[],weeks=[];qs.forEach(function(q){(gwq(yr,q)||[]).forEach(function(w){if(months.indexOf(w.month)<0)months.push(w.month);weeks.push(w);});});var mSel=mEl.value,wSel=wEl.value;mEl.innerHTML='<option value="all">All</option>'+months.map(function(m){return '<option'+(m===mSel?' selected':'')+'>'+m+'</option>';}).join('');wEl.innerHTML='<option value="all">All</option>'+weeks.map(function(w){return '<option value="'+w.key+'"'+(w.key===wSel?' selected':'')+'>'+(w.label||w.key)+'</option>';}).join('');}catch(e){}}
function cmSetView(view){
  var yr=document.getElementById('cmFYr'),q=document.getElementById('cmFQ'),rep=document.getElementById('cmFR'),fault=document.getElementById('cmFF'),mo=document.getElementById('cmFM'),wk=document.getElementById('cmFW');
  if(view==='current'){if(yr)yr.value=String(getYr());if(q)q.value=getQ();if(rep)rep.value='all';if(fault)fault.value='all';if(mo)mo.value='all';if(wk)wk.value='all';}
  if(view==='week'){if(yr)yr.value=String(getYr());if(q)q.value=getQ();if(rep)rep.value='all';if(fault)fault.value='all';if(mo)mo.value='all';if(typeof _cmPopMWeek==='function')_cmPopMWeek();var ck=_cmCurrentWeekKey();if(wk&&ck)wk.value=ck;}
  if(view==='rep'){if(fault)fault.value='rep';}
  if(view==='all'){if(yr)yr.value='all';if(q)q.value='all';if(rep)rep.value='all';if(fault)fault.value='all';if(mo)mo.value='all';if(wk)wk.value='all';}
  renderCML();
}
function renderCML(){
  _cmNormalize();
  if(typeof _cmPopMWeek==='function')_cmPopMWeek();
  var fm=document.getElementById('cmFM')?.value||'all';
  var fw=document.getElementById('cmFW')?.value||'all';
  var fr=document.getElementById('cmFR')?.value||'all';
  fr=String(fr).replace(/ \(retired\)$/,'');
  var ff=document.getElementById('cmFF')?.value||'all';
  var fyr=document.getElementById('cmFYr')?.value||'all';
  var fq=document.getElementById('cmFQ')?.value||'all';
  var f=(S.cms||[]).filter(function(c){
    var repName=String(c.rep||'').replace(/ \(retired\)$/,'');
    return (fr==='all'||repName===fr)&&(ff==='all'||c.fault===ff)&&(fyr==='all'||String(c.yr)===String(fyr))&&(fq==='all'||c.q===fq)&&(fm==='all'||String(c.weekKey||'').split('_')[2]===fm)&&(fw==='all'||c.weekKey===fw);
  });
  var tot=f.reduce(function(s,c){return s+(Number(c.amount)||0);},0);
  var repList=f.filter(function(c){return c.fault==='rep';});
  var custList=f.filter(function(c){return c.fault==='customer';});
  var rtRep=repList.reduce(function(s,c){return s+(Number(c.amount)||0);},0);
  var rtCust=custList.reduce(function(s,c){return s+(Number(c.amount)||0);},0);
  var avg=f.length?tot/f.length:0;
  _cmSetText('cmKpiTotal',_cmMoney(tot));
  _cmSetText('cmKpiCount',f.length+' memo'+(f.length===1?'':'s')+' in current view');
  _cmSetText('cmKpiRep',_cmMoney(rtRep));
  _cmSetText('cmKpiRepSub',(tot?((rtRep/tot)*100).toFixed(1):'0')+'% of filtered dollars · '+repList.length+' case'+(repList.length===1?'':'s'));
  _cmSetText('cmKpiCust',_cmMoney(rtCust));
  _cmSetText('cmKpiCustSub',(tot?((rtCust/tot)*100).toFixed(1):'0')+'% of filtered dollars · '+custList.length+' case'+(custList.length===1?'':'s'));
  _cmSetText('cmKpiAvg',_cmMoney(avg));
  var byFault={};
  f.forEach(function(c){var k=c.fault||'other';if(!byFault[k])byFault[k]={count:0,total:0};byFault[k].count++;byFault[k].total+=Number(c.amount)||0;});
  var faultRows=Object.keys(byFault).sort(function(a,b){return byFault[b].total-byFault[a].total;});
  _cmSetHtml('cmSum',f.length?'<div class="chip"><div class="cv">'+_cmMoney(tot)+'</div><div class="cl">Filtered total ('+f.length+')</div></div>'+faultRows.map(function(k){var color=k==='rep'?'#E24B4A':k==='customer'?'#D4537E':k==='vendor'?'#EF9F27':'#8B8A94';return '<div class="chip" style="border-left:3px solid '+color+';"><div class="cv" style="color:'+color+';">'+_cmMoney(byFault[k].total)+'</div><div class="cl">'+(FL[k]||k)+' · '+byFault[k].count+'</div></div>';}).join(''):'<div class="chip"><div class="cv">$0.00</div><div class="cl">No memos match the filters</div></div>');
  var topRep=null,repTotals={};
  f.forEach(function(c){var r=c.rep||'Unassigned';if(!repTotals[r])repTotals[r]={count:0,total:0,repFault:0};repTotals[r].count++;repTotals[r].total+=Number(c.amount)||0;if(c.fault==='rep')repTotals[r].repFault+=Number(c.amount)||0;});
  Object.keys(repTotals).forEach(function(r){if(!topRep||repTotals[r].total>repTotals[topRep].total)topRep=r;});
  var topFault=faultRows[0];
  var readout='';
  if(!f.length){
    readout='<div class="credit-readout-empty">No credit memos in the current view. Adjust the filters or choose <strong>All records</strong>.</div>';
  }else{
    readout='<div style="display:grid;gap:10px;">'
      +'<div><strong>'+f.length+' credit memo'+(f.length===1?'':'s')+'</strong> totaling <strong>'+_cmMoney(tot)+'</strong> in the filtered view.</div>'
      +'<div><strong>Rep-fault coaching impact:</strong> '+_cmMoney(rtRep)+' across '+repList.length+' case'+(repList.length===1?'':'s')+'. '+(rtRep>0?'Review patterns for avoidable order-entry, quote, product, or communication issues.':'No rep-fault cost in this view.')+'</div>'
      +'<div><strong>Largest fault bucket:</strong> '+(topFault?(FL[topFault]||topFault)+' at '+_cmMoney(byFault[topFault].total)+' across '+byFault[topFault].count+' case'+(byFault[topFault].count===1?'':'s'):'—')+'.</div>'
      +'<div><strong>Most impacted rep/customer owner:</strong> '+(topRep?topRep+' · '+_cmMoney(repTotals[topRep].total)+' across '+repTotals[topRep].count+' case'+(repTotals[topRep].count===1?'':'s'):'—')+'.</div>'
      +'<div style="color:var(--color-text-secondary);font-size:11px;line-height:1.5;">Use this readout for coaching: rep-fault memos indicate preventable breakdowns; customer/vendor/production categories are tracked for process visibility and should not automatically count against the rep.</div>'
      +'</div>';
  }
  _cmSetHtml('cmQualityReadout',readout);
  var el=document.getElementById('cmLog');
  if(!el)return;
  if(!f.length){el.innerHTML='<p style="font-size:12px;color:var(--color-text-secondary);padding:.4rem 0;">No credit memos found.</p>';return;}
  el.innerHTML=f.slice().sort(function(a,b){return (b.id||0)-(a.id||0);}).map(function(c){
    var amt=Number(c.amount)||0;
    return '<div class="log-row" id="cm_row_'+c.id+'"><div class="editable-row"><div style="flex:1;"><div style="display:flex;align-items:center;gap:7px;flex-wrap:wrap;margin-bottom:4px;"><span style="font-size:12px;font-weight:500;">'+(c.rep||'Unassigned')+'</span>'+faultBadge(c.fault)+'<span style="font-size:12px;font-weight:500;color:'+(c.fault==='rep'?'#E24B4A':c.fault==='customer'?'#D4537E':'var(--color-text-primary)')+';">'+_cmMoney(amt)+'</span><span style="font-size:11px;color:var(--color-text-secondary);">'+String(c.weekKey||'').replace(/_/g,' ')+'</span></div><div class="cm-detail">'+(c.custId?'<span><strong>Cust ID:</strong> '+c.custId+'</span>':'')+(c.custName?'<span><strong>Customer:</strong> '+c.custName+'</span>':'')+(c.soNum?'<span><strong>SO:</strong> '+c.soNum+'</span>':'')+(c.invNum?'<span><strong>Invoice:</strong> '+c.invNum+'</span>':'')+(c.desc?'<span>'+c.desc+'</span>':'')+'</div></div><div style="display:flex;gap:5px;flex-shrink:0;">'+pencil('editCM('+c.id+')')+'<button class="rbtn" onclick="deleteCM('+c.id+')" style="font-size:10px;padding:2px 5px;">✕</button></div></div><div id="cm_edit_'+c.id+'"></div></div>';
  }).join('');
}
function editCM(id){let c=S.cms.find(x=>x.id===id);if(!c)return;document.querySelectorAll('.inline-edit-box').forEach(el=>el.remove());let box=document.getElementById('cm_edit_'+id);if(!box)return;let faultOpts=Object.entries(FL).map(([k,l])=>'<option value="'+k+'"'+(c.fault===k?' selected':'')+'>'+l+'</option>').join('');let weekOpts=gwq(parseInt(c.yr),c.q).map(w=>'<option value="'+w.key+'"'+(c.weekKey===w.key?' selected':'')+'>'+w.label+'</option>').join('');box.innerHTML='<div class="inline-edit-box"><div class="ig"><label>Rep</label><select id="cmie_rep_'+id+'">'+S.reps.map(r=>'<option'+(c.rep===r.name?' selected':'')+'>'+r.name+'</option>').join('')+'</select></div><div class="ig"><label>Week</label><select id="cmie_wk_'+id+'">'+weekOpts+'</select></div><div class="ig"><label>Amount ($)</label><input id="cmie_amt_'+id+'" type="number" value="'+c.amount+'" min="0" step="0.01" style="width:80px;"></div><div class="ig"><label>Fault</label><select id="cmie_flt_'+id+'">'+faultOpts+'</select></div><div class="ig"><label>Customer ID</label><input id="cmie_cid_'+id+'" type="text" value="'+(c.custId||'')+'" style="width:90px;"></div><div class="ig"><label>Customer name</label><input id="cmie_cname_'+id+'" type="text" value="'+(c.custName||'')+'" style="min-width:130px;"></div><div class="ig"><label>Sales order #</label><input id="cmie_so_'+id+'" type="text" value="'+(c.soNum||'')+'" style="width:110px;"></div><div class="ig"><label>Invoice #</label><input id="cmie_inv_'+id+'" type="text" value="'+(c.invNum||'')+'" style="width:110px;"></div><div class="ig" style="flex:1;min-width:200px;"><label>Description</label><textarea id="cmie_desc_'+id+'">'+(c.desc||'')+'</textarea></div><div style="display:flex;gap:6px;width:100%;margin-top:4px;"><button class="ie-save" onclick="saveCMEdit('+id+')">✓ Save</button><button class="ie-cancel" onclick="document.getElementById(\'cm_edit_'+id+'\').innerHTML=\'\'">Cancel</button></div></div>';}
