   +'#gs-page .gs-loop{display:flex;flex-wrap:wrap;gap:6px;}'
   +'#gs-page .gs-loop .st{flex:1;min-width:90px;text-align:center;font-size:10px;font-weight:800;padding:8px 6px;border:1px solid var(--gsl);border-radius:9px;cursor:pointer;color:var(--gsm);}'
   +'#gs-page .gs-loop .st.on{background:linear-gradient(135deg,#FA873D,#FA873D);border-color:transparent;color:#fff;}'
   +'#gs-page .gs-tabs{display:flex;flex-wrap:wrap;gap:5px;margin-bottom:10px;}'
   +'#gs-page .gs-tab{font-size:10.5px;font-weight:700;padding:5px 9px;border:1px solid var(--gsl);border-radius:8px;cursor:pointer;color:var(--gsm);}'
   +'#gs-page .gs-tab.on{background:#20263180;border-color:#FA873D;color:#fff;}'
   +'#gs-page textarea.gs-ta{width:100%;min-height:220px;background:rgba(0,0,0,.25);border:1px solid var(--gsl);border-radius:10px;color:inherit;font-size:12.5px;line-height:1.55;padding:11px;font-family:inherit;resize:vertical;}'
   +'#gs-page .gs-console{max-height:420px;overflow-y:auto;padding-right:4px;}'
   +'#gs-page .gs-msg{border:1px solid var(--gsl);border-radius:10px;padding:9px 11px;margin-bottom:8px;font-size:12px;line-height:1.55;white-space:pre-wrap;}'
   +'#gs-page .gs-msg.user{background:rgba(250,135,61,.08);border-color:rgba(250,135,61,.4);font-weight:700;}'
   +'#gs-page .gs-msg.ai{background:rgba(255,255,255,.02);}'
   +'#gs-page .gs-msg .add{font-size:10px;font-weight:800;color:#FA873D;cursor:pointer;margin-top:6px;display:inline-block;}'
