 var head=stat?('<div class="rp2-grid">'+_rp2KPI('Order sales',_rp2$(stat.sales),'')+_rp2KPI('Orders',stat.orders,'')+_rp2KPI('AOV',_rp2$(stat.aov),'')+_rp2KPI('New customers',stat.newCust,'')+'</div>'):'';
 if(!os.length)return head+'<div class="rp2-card">No uploaded orders for you yet.</div>';
