 return head+'<div class="rp2-card"><div class="rp2-ch">Your orders (latest '+Math.min(60,os.length)+' of '+os.length+')</div><table class="rp2-tbl"><thead><tr><th style="text-align:left;">Date</th><th style="text-align:left;">Order #</th><th style="text-align:left;">Customer</th><th style="text-align:left;">Type</th><th>Total</th></tr></thead><tbody>'+rows+'</tbody></table></div>';
