  +'.hdr-r{text-align:right;min-width:190px;}.hdr-type{font-size:9px;text-transform:uppercase;letter-spacing:.14em;font-weight:900;color:#A7F3D0;}.hdr-title{font-size:20px;font-weight:950;letter-spacing:-.03em;line-height:1.08;margin-top:3px;}.hdr-date{font-size:9.5px;color:rgba(255,255,255,.70);margin-top:5px;}'
  +'.bod{padding:14px 20px 16px;}'
