  +'.sec,.section{background:#fff;border:1px solid #E4E7EC;border-radius:12px;padding:11px 13px;margin:0 0 10px;break-inside:avoid;page-break-inside:avoid;}'
  +'.sec.flow{break-inside:auto;page-break-inside:auto;}'
  +'.sec-h,.sec-title{display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:10px;font-weight:950;text-transform:uppercase;letter-spacing:.09em;color:#334155;border-bottom:2px solid #151515;padding-bottom:5px;margin-bottom:8px;}'
