  +'.exec-box{background:linear-gradient(135deg,#0F1424,#1A2440);color:#EEF1FB;border-radius:12px;padding:14px 17px;font-size:11.6px;line-height:1.65;break-inside:avoid;page-break-inside:avoid;margin:0 0 10px;}'
  +'.exec-box .eyebrow{font-size:8.5px;font-weight:900;text-transform:uppercase;letter-spacing:.12em;color:#00AFEF;margin-bottom:6px;}'
  +'.kgrid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px;}'
  +'.k{background:linear-gradient(180deg,#fff,#F8FAFC);border:1px solid #E6EAF0;border-radius:10px;padding:8px 10px;break-inside:avoid;page-break-inside:avoid;}'
  +'.k .kl{font-size:7.6px;font-weight:950;text-transform:uppercase;letter-spacing:.07em;color:#667085;margin-bottom:3px;white-space:nowrap;}'
  +'.k .kv{font-size:15.5px;font-weight:950;letter-spacing:-.03em;line-height:1.05;}'
  +'.k .ks{font-size:8.3px;color:#667085;margin-top:3px;}'
  +'.note{border:1px solid #BFDBFE;background:#EFF6FF;border-radius:10px;padding:10px 13px;font-size:10.6px;color:#1E3A8A;line-height:1.6;break-inside:avoid;page-break-inside:avoid;}'
  +'.fc-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;}'
  +'.fc-card{background:linear-gradient(180deg,#fff,#F8FAFC);border:1px solid #E6EAF0;border-radius:10px;padding:9px 10px;break-inside:avoid;page-break-inside:avoid;}'
  +'.fc-label{font-size:7.8px;font-weight:950;text-transform:uppercase;letter-spacing:.08em;color:#667085;margin-bottom:4px;}.fc-val{font-size:16px;font-weight:950;letter-spacing:-.03em;}.fc-sub{font-size:8.4px;color:#667085;margin-top:4px;}'
