  +'.bar{width:56px;height:5px;background:#EEF2F6;border-radius:999px;overflow:hidden;display:inline-block;vertical-align:middle;}.bar-fill{height:100%;border-radius:999px;display:block;}'
  +'.spk{display:flex;align-items:flex-end;gap:2px;height:52px;margin-top:4px;}.spk-c{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%;}.spk-b{width:76%;border-radius:2px 2px 0 0;min-height:2px;}.spk-x{font-size:5.6px;color:#B6BAC4;margin-top:2px;line-height:1;}'
  +'.pod-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px;}'
  +'.pod{border:1px solid #E4E7EC;border-radius:12px;padding:12px;text-align:center;break-inside:avoid;page-break-inside:avoid;background:linear-gradient(180deg,#fff,#F8FAFC);}'
  +'.pod.g1{border-color:#F59E0B;background:linear-gradient(180deg,#FFFBEB,#fff);}.pod.g2{border-color:#94A3B8;}.pod.g3{border-color:#FB923C;}'
  +'.pod .medal{font-size:19px;}.pod .pname{font-size:12.5px;font-weight:900;margin-top:3px;}.pod .prev{font-size:17px;font-weight:950;letter-spacing:-.03em;margin-top:4px;}.pod .psub{font-size:8.8px;color:#667085;margin-top:3px;}'
  +'.rb-av{display:inline-flex;align-items:center;justify-content:center;width:26px;height:26px;border-radius:50%;background:#111B2E;color:#fff;font-size:9.5px;font-weight:900;letter-spacing:.02em;flex:none;}'
  +'.rep-block{border:1px solid #E4E7EC;border-left:3px solid #008CC0;border-radius:10px;padding:10px 12px;margin:0 0 9px;break-inside:avoid;page-break-inside:avoid;}'
  +'.rep-block .rb-hdr{display:flex;align-items:center;gap:8px;margin-bottom:7px;}'
  +'.rep-block .rb-name{font-size:12px;font-weight:900;}.rep-block .rb-rank{font-size:8px;font-weight:900;background:#FFFFFF;color:#4F46E5;padding:2px 8px;border-radius:20px;}'
  +'.rep-block .rb-rev{margin-left:auto;font-size:14px;font-weight:950;letter-spacing:-.02em;}'
  +'.rb-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:6px;margin-bottom:6px;}'
  +'.rb-cell{background:#F8FAFC;border:1px solid #EEF1F5;border-radius:8px;padding:6px 8px;}'
  +'.rb-cell .l{font-size:7px;font-weight:950;text-transform:uppercase;letter-spacing:.06em;color:#667085;}.rb-cell .v{font-size:11px;font-weight:900;margin-top:2px;}.rb-cell .s{font-size:7.6px;color:#8A94A6;margin-top:1px;}'
  +'.rb-ai{font-size:9.8px;line-height:1.55;background:#FFFFFF;border-left:2px solid #4F46E5;border-radius:0 8px 8px 0;padding:6px 9px;margin-top:5px;color:#1E1B4B;}'
