  +'.hero-band{background:linear-gradient(135deg,#065F46,#0E7490 60%,#1D4ED8);color:#fff;border-radius:14px;padding:16px 18px;margin:0 0 10px;break-inside:avoid;page-break-inside:avoid;}'
  +'.hero-band .hb-eyebrow{font-size:8.5px;font-weight:900;text-transform:uppercase;letter-spacing:.13em;color:#A7F3D0;}'
  +'.hero-band .hb-title{font-size:18px;font-weight:950;letter-spacing:-.02em;margin-top:2px;}'
  +'.hero-band .hb-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin-top:10px;}'
