    b.style.cssText='position:fixed;top:0;left:0;right:0;z-index:99999;background:#7F1D1D;color:#fff;padding:10px 16px;font:700 13px/1.4 -apple-system,Segoe UI,Roboto,sans-serif;display:flex;gap:12px;align-items:center;flex-wrap:wrap;box-shadow:0 4px 20px rgba(0,0,0,.5);';
    b.innerHTML='<span>\u26a0\ufe0f DATA IS NOT SAVING on this device ('+((err&&err.name)||'storage error')+'). Your work only exists in this open tab \u2014 do NOT close or refresh. A backup file is downloading now; keep it safe.</span>'
      +'<button onclick="try{exportAllData()}catch(e){alert(e)}" style="background:#fff;color:#7F1D1D;border:0;border-radius:8px;padding:6px 12px;font-weight:800;cursor:pointer;">Download backup again</button>';
