function loadFromStorage(){
  if(!_lsAvailable())return false;
  try{
    var raw=localStorage.getItem(STORE_KEY);
    if(!raw)return false;
    var saved=JSON.parse(raw);
    if(!saved||!saved.reps)return false;
    S.reps=(saved.reps||[]).filter(function(r){return r&&typeof r.name==='string'&&r.name.trim().length>0;});
    S.goals=saved.goals||{};
    S.data=saved.data||{};
    S.cms=saved.cms||[];
    S.artErrors=saved.artErrors||[];
    S.artErrorSource=saved.artErrorSource||S.artErrorSource||{url:"",lastSync:null,lastCount:0};
    S.artErrorIgnored=saved.artErrorIgnored||S.artErrorIgnored||[];
    S.hrViolations=(saved.hrViolations||[]).map(function(v){if(v.points!==undefined&&v.pts===undefined)v.pts=v.points;return v;});
    S.coachingNotes=saved.coachingNotes||[];
    S.dailySales=saved.dailySales||[];
    S.customers=saved.customers||[];
    S.reviews=saved.reviews||{url:'',rows:[],lastFetched:null,decisions:{},unmatchFix:{}};
    S.orders=saved.orders||[];S.ordersMeta=saved.ordersMeta||{};S.orderLineItems=saved.orderLineItems||[];S.orderLineItemsMeta=saved.orderLineItemsMeta||{version:1,imports:[]};S.orderLineItemsUnmatched=saved.orderLineItemsUnmatched||[];S.gamestorm=saved.gamestorm||{projects:[],activeId:null};S.priorYear=saved.priorYear||{};S.repPortal=saved.repPortal||{managerHash:'',accounts:{},sections:['sales','orders','art','credits','reviews','coaching','rank'],enabled:false};
    S.dailyRep=saved.dailyRep||{};
    S.cx586ov=saved.cx586ov||{};
    S.companyKnowledge=saved.companyKnowledge||{categories:{},freeform:'',lastUpdated:null};S.customers=saved.customers||S.customers||[];S.orders=saved.orders||S.orders||[];S.ordersMeta=saved.ordersMeta||S.ordersMeta||{};S.orderLineItems=saved.orderLineItems||[];S.orderLineItemsMeta=saved.orderLineItemsMeta||{version:1,imports:[]};S.orderLineItemsUnmatched=saved.orderLineItemsUnmatched||[];
    S.teamGoals=saved.teamGoals||{};
    S.reps.forEach(function(r){if(!r.profile)r.profile={};if(r.retired===undefined)r.retired=false;});
    loadPhotos();
    return true;
  }catch(e){
    console.warn('Load from storage failed:',e);
    return false;
  }
}
