// ─── DATE HELPERS FOR EVENT RESOLUTION ───────────────────────────────────────
// Resolve special day specs like '1st-friday', '3rd-monday', '2nd-sunday', 'last-friday', '1st-week', '3rd-week', '4th-thursday'
function _resolveEventDate(yr, ev){
  var m=ev.month, day=ev.day;
  if(typeof day==='number'){
    return new Date(yr, m, day);
  }
  if(typeof day==='string'){
    var parts=day.split('-');
    var which=parts[0]; // 1st, 2nd, 3rd, 4th, last
    var weekday=parts[1]; // monday, tuesday, ..., week
    var weekdayMap={sunday:0,monday:1,tuesday:2,wednesday:3,thursday:4,friday:5,saturday:6};
    if(weekday==='week'){
      // e.g. '1st-week' = first day of the first full week of the month (use the 1st-7th)
      var weekNum={'1st':0,'2nd':1,'3rd':2,'4th':3}[which]||0;
      return new Date(yr, m, 1 + weekNum*7);
    }
    if(!(weekday in weekdayMap))return new Date(yr, m, 1);
    var target=weekdayMap[weekday];
    if(which==='last'){
      // Last [weekday] of month
      var lastDay=new Date(yr, m+1, 0);
      var lastDow=lastDay.getDay();
      var offset=(lastDow-target+7)%7;
      return new Date(yr, m, lastDay.getDate()-offset);
    } else {
      var nth={'1st':1,'2nd':2,'3rd':3,'4th':4,'5th':5}[which]||1;
      var firstOfMonth=new Date(yr, m, 1);
      var firstDow=firstOfMonth.getDay();
      var offset=(target-firstDow+7)%7;
      return new Date(yr, m, 1+offset+(nth-1)*7);
    }
  }
  return new Date(yr, m, 1);
}

// Find this year's (or next year's) occurrence of each event, returning sorted by date
function _resolveAllEvents(){
  var today=new Date(); today.setHours(0,0,0,0);
  var thisYr=today.getFullYear();
  var resolved=[];
  var sourceEvents=_forecastAllEvents();
  sourceEvents.forEach(function(ev){
    var d=_resolveEventDate(thisYr, ev);
    if(d<today){
      d=_resolveEventDate(thisYr+1, ev);
    }
    var daysAway=Math.round((d.getTime()-today.getTime())/(86400000));
    resolved.push(Object.assign({}, ev, {date:d, daysAway:daysAway, _ai:_forecastAiEvents&&_forecastAiEvents.indexOf(ev)>=0}));
  });
  resolved.sort(function(a,b){return a.daysAway-b.daysAway;});
  return resolved;
}

// Get current quarter as months 0-2 of the quarter
function _currentQuarterMonths(){
  var m=new Date().getMonth();
  if(m<3)return [0,1,2];
  if(m<6)return [3,4,5];
  if(m<9)return [6,7,8];
  return [9,10,11];
}
function _nextQuarterMonths(){
  var m=new Date().getMonth();
  if(m<3)return [3,4,5];
  if(m<6)return [6,7,8];
  if(m<9)return [9,10,11];
  return [0,1,2];
}

function _formatRange(start, end){
  var f=function(d){return d.toLocaleDateString('en-US',{month:'short',day:'numeric'});};
  return f(start)+' \u2014 '+f(end);
}

// Category styling
var FORECAST_CATEGORY_COLORS = {
  holiday:'#F09595', awareness:'#8EDCFA', employee:'#5DCAA5',
  industry:'#EF9F27', seasonal:'#FA873D', sports:'#00AFEF'
};
var FORECAST_CATEGORY_LABELS = {
  holiday:'Holiday', awareness:'Awareness', employee:'Employee Appreciation',
  industry:'Industry Event', seasonal:'Seasonal', sports:'Sports'
};

function _renderForecastCard(ev){
  var col=FORECAST_CATEGORY_COLORS[ev.category]||'#FA873D';
  var lbl=FORECAST_CATEGORY_LABELS[ev.category]||ev.category;
  var dateStr=ev.date.toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'});
  var daysBadge=ev.daysAway<=0?'TODAY':ev.daysAway===1?'TOMORROW':ev.daysAway<=7?'in '+ev.daysAway+' days':ev.daysAway<=30?'in '+ev.daysAway+' days':'in '+Math.round(ev.daysAway/7)+' weeks';
  var html='<div style="border:1px solid '+col+'55;border-left:4px solid '+col+';border-radius:8px;padding:12px 16px;background:var(--color-background-secondary);margin-bottom:10px;">';
  html+='<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:6px;flex-wrap:wrap;">';
  html+='<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;"><span style="font-size:14px;font-weight:700;color:var(--color-text-primary);">'+esc_html(ev.name)+'</span>';
  html+='<span style="font-size:9px;font-weight:600;text-transform:uppercase;padding:2px 8px;border-radius:10px;background:'+col+'22;color:'+col+';">'+lbl+'</span>';
  if(ev._ai)html+='<span style="font-size:9px;font-weight:600;padding:2px 8px;border-radius:10px;background:rgba(250,135,61,0.15);color:#8EDCFA;" title="Added by AI verification">&#10024; AI</span>';
  html+='</div>';
  html+='<div style="font-size:11px;color:var(--color-text-secondary);"><strong style="color:'+col+';">'+dateStr+'</strong> &middot; '+daysBadge+'</div>';
  html+='</div>';
  if(ev.pitch)html+='<div style="font-size:12px;color:var(--color-text-primary);line-height:1.5;margin-bottom:8px;">'+esc_html(ev.pitch)+'</div>';
  if(ev.targetCustomers)html+='<div style="font-size:11px;color:var(--color-text-secondary);margin-bottom:6px;"><strong style="color:'+col+';">Target:</strong> '+esc_html(ev.targetCustomers)+'</div>';
  if(ev.products&&ev.products.length){
    html+='<div style="margin-bottom:6px;"><div style="font-size:10px;font-weight:600;color:#5DCAA5;text-transform:uppercase;margin-bottom:3px;">What to sell</div>';
    html+='<div style="display:flex;flex-wrap:wrap;gap:4px;">';
    ev.products.forEach(function(p){
      html+='<span style="display:inline-block;font-size:11px;padding:3px 9px;border-radius:11px;background:rgba(93,202,165,.10);color:#5DCAA5;border:0.5px solid rgba(93,202,165,.30);">'+esc_html(p)+'</span>';
    });
    html+='</div></div>';
  }
  if(ev.leadTime)html+='<div style="font-size:11px;color:#EF9F27;margin-bottom:6px;"><strong>Lead time:</strong> '+esc_html(ev.leadTime)+'</div>';
  if(ev.callOpener)html+='<div style="font-size:11px;background:rgba(250,135,61,.08);border-left:2px solid #FA873D;padding:6px 10px;border-radius:0 6px 6px 0;color:var(--color-text-primary);font-style:italic;">&ldquo;'+esc_html(ev.callOpener)+'&rdquo;</div>';
  html+='</div>';
  return html;
}

function _renderDowntimeCard(d){
  var todayMo=new Date().getMonth();
  var isDown=d.downMonths.length===0||d.downMonths.indexOf(todayMo)>=0;
  if(!isDown)return ''; // Skip industries not in downtime right now
  var html='<div style="border:1px solid #FA873D55;border-left:4px solid #FA873D;border-radius:8px;padding:12px 16px;background:var(--color-background-secondary);margin-bottom:10px;">';
  html+='<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:6px;">';
  html+='<span style="font-size:13px;font-weight:700;color:#8EDCFA;">'+(d.icon||'')+' '+esc_html(d.industry)+'</span>';
  html+='<span style="font-size:9px;font-weight:600;padding:2px 8px;border-radius:10px;background:rgba(250,135,61,.18);color:#8EDCFA;text-transform:uppercase;">\uD83D\uDCA4 In Downtime</span>';
  html+='</div>';
  if(d.whyDowntime)html+='<div style="font-size:11px;color:var(--color-text-secondary);line-height:1.5;margin-bottom:6px;"><strong style="color:#8EDCFA;">Why slow:</strong> '+esc_html(d.whyDowntime)+'</div>';
  if(d.whyAnswerNow)html+='<div style="font-size:11px;color:var(--color-text-primary);background:rgba(250,135,61,.08);border-left:2px solid #FA873D;padding:6px 10px;border-radius:0 6px 6px 0;margin-bottom:6px;"><strong style="color:#8EDCFA;">\u260E Why they\'ll answer:</strong> '+esc_html(d.whyAnswerNow)+'</div>';
  if(d.pitchFor)html+='<div style="font-size:12px;color:var(--color-text-primary);line-height:1.5;margin-bottom:6px;"><strong style="color:#5DCAA5;">Pitch for:</strong> '+esc_html(d.pitchFor)+'</div>';
  if(d.busySeasonStarts)html+='<div style="font-size:10px;color:#EF9F27;font-weight:600;margin-bottom:6px;">\uD83D\uDDD3 Their busy season starts: '+esc_html(d.busySeasonStarts)+'</div>';
  if(d.products&&d.products.length){
    html+='<div style="margin-bottom:6px;"><div style="font-size:10px;font-weight:600;color:#5DCAA5;text-transform:uppercase;margin-bottom:3px;">What to sell</div>';
    html+='<div style="display:flex;flex-wrap:wrap;gap:4px;">';
    d.products.forEach(function(p){
      html+='<span style="display:inline-block;font-size:11px;padding:3px 9px;border-radius:11px;background:rgba(93,202,165,.10);color:#5DCAA5;border:0.5px solid rgba(93,202,165,.30);">'+esc_html(p)+'</span>';
    });
    html+='</div></div>';
  }
  if(d.leadTime)html+='<div style="font-size:11px;color:#EF9F27;margin-bottom:6px;"><strong>Lead time:</strong> '+esc_html(d.leadTime)+'</div>';
  if(d.callOpener)html+='<div style="font-size:11px;background:rgba(250,135,61,.08);border-left:2px solid #FA873D;padding:6px 10px;border-radius:0 6px 6px 0;color:var(--color-text-primary);font-style:italic;">&ldquo;'+esc_html(d.callOpener)+'&rdquo;</div>';
  html+='</div>';
  return html;
}

function renderForecast(){
  var today=new Date(); today.setHours(0,0,0,0);
  var resolved=_resolveAllEvents();
  // Time windows
  var nextWeekEnd=new Date(today.getTime()+7*86400000);
  var endOfMonth=new Date(today.getFullYear(), today.getMonth()+1, 0);
  var curQ=_currentQuarterMonths();
  var endOfQuarter=new Date(today.getFullYear(), curQ[2]+1, 0);
  var nextQ=_nextQuarterMonths();
  var nextQyr=nextQ[0]<curQ[0]?today.getFullYear()+1:today.getFullYear();
  var nextQstart=new Date(nextQyr, nextQ[0], 1);
  var nextQend=new Date(nextQyr, nextQ[2]+1, 0);

  // Buckets
  var nextWeek=resolved.filter(function(ev){return ev.date>=today&&ev.date<=nextWeekEnd;});
  var thisMonth=resolved.filter(function(ev){return ev.date>nextWeekEnd&&ev.date<=endOfMonth;});
  var thisQuarter=resolved.filter(function(ev){return ev.date>endOfMonth&&ev.date<=endOfQuarter;});
  var nextQuarter=resolved.filter(function(ev){return ev.date>=nextQstart&&ev.date<=nextQend;});

  // Update date range labels
  var setLbl=function(id,text){var el=document.getElementById(id);if(el)el.textContent=text;};
  setLbl('nextWeekRange',_formatRange(today,nextWeekEnd));
  setLbl('thisMonthRange',_formatRange(new Date(nextWeekEnd.getTime()+86400000),endOfMonth));
  setLbl('thisQuarterRange',_formatRange(new Date(endOfMonth.getTime()+86400000),endOfQuarter));
  setLbl('nextQuarterRange',_formatRange(nextQstart,nextQend));

  // Render each section
  var renderSection=function(elId, events, emptyMsg){
    var el=document.getElementById(elId); if(!el)return;
    if(events.length===0){
      el.innerHTML='<p style="font-size:12px;color:var(--color-text-secondary);font-style:italic;">'+emptyMsg+'</p>';
      return;
    }
    el.innerHTML=events.map(_renderForecastCard).join('');
  };
  renderSection('forecastNextWeek',nextWeek,'Nothing major in the next 7 days. Catch your breath \u2014 use this time to follow up on prior pitches.');
  renderSection('forecastThisMonth',thisMonth,'No additional events lined up this month beyond what\'s in the next-week section.');
  renderSection('forecastThisQuarter',thisQuarter,'Quiet quarter ahead. Focus on relationship-building and existing-customer expansion.');
  renderSection('forecastNextQuarter',nextQuarter,'Next quarter has no events loaded yet \u2014 check back as we get closer.');

  // Downtime section
  var dt=document.getElementById('forecastDowntime');
  if(dt){
    var downCards=TCP_DOWNTIME_INDUSTRIES.map(_renderDowntimeCard).filter(function(x){return x;}).join('');
    if(downCards){dt.innerHTML=downCards;}
    else{dt.innerHTML='<p style="font-size:12px;color:var(--color-text-secondary);font-style:italic;">No industries in deep downtime right now. Everyone\'s in their busy season \u2014 push current opportunities hard.</p>';}
  }

  // Generated timestamp
  var ts=document.getElementById('intelTimestamp');
  if(ts){
    var totalCount=_forecastAllEvents().length;
    var baseCount=TCP_FORECAST_EVENTS.length;
    var aiCount=_forecastAiEvents?_forecastAiEvents.length:0;
    var summary=aiCount>0
      ? totalCount+' events ('+baseCount+' baseline + '+aiCount+' AI-added)'
      : baseCount+' baseline events';
    ts.innerHTML=summary+' &middot; '+today.toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'});
  }
  // Show reset button if AI events present
  var resetBtn=document.getElementById('forecastResetBtn');
  if(resetBtn)resetBtn.style.display=(_forecastAiEvents&&_forecastAiEvents.length)?'inline-block':'none';
}

function initIntelTab(){
  // Load AI-enriched events from storage (if any), then render
  _forecastLoadAiEvents();
  renderForecast();
}

// ─── AI VERIFY / ENHANCE FORECAST EVENTS ─────────────────────────────────────
var FORECAST_AI_STORE='salesTracker_forecastAiEvents_v1';
var _forecastAiEvents=null;   // array of AI-supplied events (merged into TCP_FORECAST_EVENTS at render time)
var _forecastAiMeta=null;     // {verifiedAt, addedCount, dateCorrections}
var _forecastVerifying=false;

function _forecastLoadAiEvents(){
  try{
    var s=localStorage.getItem(FORECAST_AI_STORE);
    if(!s)return;
    var obj=JSON.parse(s);
    if(obj&&Array.isArray(obj.events)){
      _forecastAiEvents=obj.events;
      _forecastAiMeta=obj.meta||null;
    }
  }catch(e){}
}
function _forecastSaveAiEvents(events,meta){
  try{localStorage.setItem(FORECAST_AI_STORE,JSON.stringify({events:events,meta:meta}));}catch(e){}
}
function _forecastClearAiEvents(){
  try{localStorage.removeItem(FORECAST_AI_STORE);}catch(e){}
  _forecastAiEvents=null;_forecastAiMeta=null;
}

// Return the working event list: baseline + AI additions, deduped by name+month
function _forecastAllEvents(){
  var combined=TCP_FORECAST_EVENTS.slice();
  if(_forecastAiEvents&&_forecastAiEvents.length){
    // De-dupe: skip AI events whose name closely matches an existing event in the same month
    var existing={};
    combined.forEach(function(ev){
      var key=ev.month+'|'+String(ev.name||'').toLowerCase().replace(/[^a-z0-9]/g,'').substring(0,20);
      existing[key]=true;
    });
    _forecastAiEvents.forEach(function(ev){
      if(typeof ev.month!=='number')return;
      var key=ev.month+'|'+String(ev.name||'').toLowerCase().replace(/[^a-z0-9]/g,'').substring(0,20);
      if(!existing[key]){
        combined.push(ev);
        existing[key]=true;
      }
    });
  }
  return combined;
}

async function verifyForecastWithAI(){
  if(_forecastVerifying)return;
  _forecastVerifying=true;
  var btn=document.getElementById('forecastVerifyBtn');
  var st=document.getElementById('forecastVerifyStatus');
  if(btn){btn.disabled=true;btn.textContent='Verifying...';}
  if(st){st.style.display='block';st.innerHTML='<span style="color:#EF9F27;">\u25CB AI is reviewing the event calendar...</span>';}

  var today=new Date();
  var todayStr=today.toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'});
  var yr=today.getFullYear();
  // Build summary of what's already in baseline (compact, just names + month)
  var existingSummary=TCP_FORECAST_EVENTS.map(function(ev){
    var dayStr=typeof ev.day==='number'?'/'+ev.day:(' ('+ev.day+')');
    return '- '+ev.name+' [month '+ev.month+dayStr+']';
  }).join('\n');

  var prompt='Today is '+todayStr+'. You are auditing the sales-event calendar for Triple Crown Products (TCP), a custom branded apparel & promotional products supplier in Mukwonago, WI.\n\n'+
    'TCP customers (primarily WI/Midwest, B2B):\n'+
    '- Construction & trades\n- Manufacturing & industrial\n- Schools & education (K-12, universities)\n- Sports teams & athletic programs\n- Healthcare facilities\n- Restaurants & hospitality\n- Government & municipal\n- Small/medium B2B services\n\n'+
    'CURRENT BASELINE EVENT LIST (already in the calendar):\n'+existingSummary+'\n\n'+
    'YOUR TASK: Suggest ADDITIONAL events for '+yr+' and early '+(yr+1)+' that are missing from the baseline above. Focus on:\n'+
    '- Employee appreciation days (e.g. Pharmacist Day, Receptionist Day, IT Pro Day, Dental Hygienist Week)\n'+
    '- Industry-specific awareness weeks (e.g. EMS Week, National Engineers Week, Construction Inclusion Week)\n'+
    '- Major sports calendar markers (Super Bowl, March Madness, World Series, NFL kickoff)\n'+
    '- Trade shows and conventions (ASI Show, PPAI Expo, SHOT Show, etc.)\n'+
    '- Less-common but selling-relevant US observances\n- Quarter-specific seasonal demand markers\n\n'+
    'SKIP:\n'+
    '- Anything already in the baseline (don\'t duplicate)\n'+
    '- Politically/socially divisive observances (Pride, partisan days, religious advocacy)\n'+
    '- Generic "National X Day" that has no clear product-selling angle for custom apparel/promo\n\n'+
    'For each suggested event, provide ALL fields with REAL content (no placeholders):\n'+
    '- month: 0-11 (0=Jan, 11=Dec)\n'+
    '- day: number 1-31 OR string like "1st-friday" / "3rd-monday" / "last-friday" / "1st-week" / "2nd-tuesday" for floating dates\n'+
    '- name: clear event name\n'+
    '- category: one of [holiday, awareness, employee, industry, seasonal, sports]\n'+
    '- industries: array of TCP customer industries this applies to\n'+
    '- products: array of 2-3 specific TCP products (e.g. "Port Authority K500 polos", "CornerStone CSV105 hi-vis vests", "20oz double-wall tumblers")\n'+
    '- pitch: 1-2 sentences on the sales angle\n'+
    '- targetCustomers: specific customer descriptor (e.g. "Hospital HR teams, clinic operations managers")\n'+
    '- leadTime: order-by deadline so production lands on time\n'+
    '- callOpener: phone opener in quotes, max 30 words\n\n'+
    'TCP PRODUCT CATEGORIES (use real product names): Port Authority K500/C800/J730, CornerStone CS410/CSV105, Sport-Tek ST350, Carhartt CT104050/CT102358/CTJ140, Port & Company PC78H, 20oz double-wall insulated tumblers, ceramic mugs, canvas totes, USB power banks, branded notebooks, lapel pins, custom medals.\n\n'+
    'Return ONLY a JSON array of event objects. Aim for 15-25 high-quality additions. Skip any you can\'t fully populate with real content.';

  try{
    var raw=await callAI(prompt,{useWebSearch:false,maxTokens:6000,skipCompanyContext:true});
    if(!raw||raw.length<100){throw new Error('AI returned an empty response. Try again in a minute.');}
    var arr=_extractJsonArray(raw);
    if(!arr||!Array.isArray(arr)){
      console.warn('[Forecast verify] AI raw response:',raw.substring(0,500));
      throw new Error('AI returned text but no parseable JSON array was found. Click verify again to retry.');
    }
    // Coerce month strings to numbers so "5" → 5; relax pitch requirement
    var validated=arr.map(function(ev){
      if(!ev)return null;
      var m=(typeof ev.month==='string')?parseInt(ev.month,10):ev.month;
      if(typeof m!=='number'||isNaN(m)||m<0||m>11)return null;
      ev.month=m;
      if(ev.day===undefined||ev.day===null||ev.day==='')return null;
      if(!ev.name||String(ev.name).length<3)return null;
      // Pitch optional — synthesize a minimal one if missing so the card has SOMETHING to show
      if(!ev.pitch||String(ev.pitch).length<3){
        ev.pitch=String(ev.name)+' &mdash; opportunity for branded gear, recognition items, or seasonal apparel.';
      }
      return ev;
    }).filter(function(ev){return ev;});
    if(validated.length===0){
      var sample=arr.slice(0,2).map(function(e){return JSON.stringify(e).substring(0,150);}).join(' | ');
      console.warn('[Forecast verify] AI returned',arr.length,'items but 0 passed. First items:',sample);
      throw new Error('AI returned '+arr.length+' event(s) but none had a valid month/day/name. Sample: '+sample.substring(0,200)+'... Try regenerating.');
    }
    var meta={verifiedAt:new Date().toISOString(),addedCount:validated.length};
    _forecastAiEvents=validated;
    _forecastAiMeta=meta;
    _forecastSaveAiEvents(validated,meta);
    renderForecast();
    if(st)st.innerHTML='<span style="color:#5DCAA5;">\u2713 AI added '+validated.length+' new events to your calendar. Total events: '+_forecastAllEvents().length+'. Verified '+new Date().toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})+'.</span>';
    var resetBtn=document.getElementById('forecastResetBtn');
    if(resetBtn)resetBtn.style.display='inline-block';
  }catch(err){
    console.error('[Forecast verify] failed:',err);
    if(st)st.innerHTML='<span style="color:#F09595;">\u26A0 '+esc_html(err.message||String(err))+'</span>';
  }finally{
    _forecastVerifying=false;
    if(btn){btn.disabled=false;btn.innerHTML='&#10024; Verify &amp; enhance with AI';}
  }
}

function resetForecastToBaseline(){
  if(!confirm('Discard AI-added events and revert to the baseline curated list?'))return;
  _forecastClearAiEvents();
  renderForecast();
  var st=document.getElementById('forecastVerifyStatus');
  if(st)st.innerHTML='<span style="color:var(--color-text-secondary);">Reset to baseline. '+TCP_FORECAST_EVENTS.length+' baseline events.</span>';
  var resetBtn=document.getElementById('forecastResetBtn');
  if(resetBtn)resetBtn.style.display='none';
}

