  var bl=document.createElement('div');bl.innerHTML='<div style="font-size:13px;font-weight:600;color:#8EDCFA;">&#127775; Personal weekly intel report'+helpBtn('personal-intel')+'</div><div style="font-size:11px;color:var(--color-text-secondary);margin-top:3px;">AI-powered coaching: pacing, calls, customer spotlight, market intel.</div>';
  var brr=document.createElement('div');brr.style.cssText='display:flex;align-items:center;gap:8px;';
