// ============== QUARTER CALENDAR OVERRIDE ==============
var QCAL_STORE='salesTracker_quarterCalendar_v1';
function loadQuarterCalendarStore(){
  try{var s=localStorage.getItem(QCAL_STORE);return s?JSON.parse(s):{};}catch(e){return {};}
}
function saveQuarterCalendarStore(obj){
  try{localStorage.setItem(QCAL_STORE,JSON.stringify(obj));}catch(e){}
}
function getCustomQStart(yr,q){
  var cal=loadQuarterCalendarStore();
  var yc=cal[String(yr)];
  if(!yc||!yc[q])return null;
  var parts=yc[q].split('-');
  if(parts.length!==3)return null;
  return new Date(parseInt(parts[0]),parseInt(parts[1])-1,parseInt(parts[2]));
}
function getCustomWeeksPerQuarter(yr){
  var cal=loadQuarterCalendarStore();
  var yc=cal[String(yr)];
  if(yc&&yc.weeksPerQuarter)return yc.weeksPerQuarter;
  return null;
}
function fmtYMD(d){
  if(!d)return '';
  var y=d.getFullYear(),m=d.getMonth()+1,da=d.getDate();
  return y+'-'+(m<10?'0':'')+m+'-'+(da<10?'0':'')+da;
}
function renderQuarterCalendar(){
  var sel=document.getElementById('qcalYr');
  if(!sel)return;
  // Populate years if empty
  if(!sel.options.length){
    var thisYr=new Date().getFullYear();
    for(var y=thisYr-2;y<=thisYr+2;y++){
      var opt=document.createElement('option');opt.value=y;opt.text=y;
      if(y===thisYr)opt.selected=true;
      sel.appendChild(opt);
    }
  }
  var yr=parseInt(sel.value);
  var cal=loadQuarterCalendarStore();
  var yc=cal[String(yr)]||{};
  
  // Render the 4 quarter inputs
  var grid=document.getElementById('qcalGrid');
  if(!grid)return;
  var quarters=['Q1','Q2','Q3','Q4'];
  var defaultLabels={Q1:'(default: Jan 1 anchor)',Q2:'(default: Apr 1 anchor → prior Sunday)',Q3:'(default: Jul 1 anchor → prior Sunday)',Q4:'(default: Oct 1 anchor → prior Sunday)'};
  grid.innerHTML=quarters.map(function(q){
    var customStart=yc[q]||'';
    var defaultStart=getQStart(yr,q);
    var defaultStr=fmtYMD(defaultStart);
    var displayDefault=defaultStart.toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'});
    return '<div style="background:rgba(250,135,61,.05);border:0.5px solid rgba(250,135,61,.25);border-radius:8px;padding:10px 12px;">'+
      '<div style="font-size:12px;font-weight:600;color:var(--color-text-primary);margin-bottom:4px;">'+q+' '+yr+' starts on</div>'+
      '<input type="date" id="qcal_'+q+'" value="'+customStart+'" style="background:var(--color-background-secondary);border:0.5px solid var(--color-border-secondary);color:var(--color-text-primary);padding:5px 7px;border-radius:5px;font-size:12px;width:100%;margin-bottom:3px;">'+
      '<div style="font-size:10px;color:var(--color-text-secondary);line-height:1.4;">Default: '+displayDefault+'<br>'+defaultLabels[q]+'</div>'+
    '</div>';
  }).join('');
  
  // Set weeks-per-quarter input
  var wpqInput=document.getElementById('qcalWeeksPerQ');
  if(wpqInput){
    wpqInput.value=yc.weeksPerQuarter||13;
  }
}
function saveQuarterCalendarUI(){
  var sel=document.getElementById('qcalYr');
  if(!sel)return;
  var yr=String(sel.value);
  var cal=loadQuarterCalendarStore();
  var yc=cal[yr]||{};
  ['Q1','Q2','Q3','Q4'].forEach(function(q){
    var inp=document.getElementById('qcal_'+q);
    if(inp){
      var v=inp.value;
      if(v)yc[q]=v; else delete yc[q];
    }
  });
  var wpq=parseInt(document.getElementById('qcalWeeksPerQ').value);
  if(wpq>=1&&wpq<=14)yc.weeksPerQuarter=wpq;else delete yc.weeksPerQuarter;
  // Clean: if year has no overrides at all, remove it
  if(!yc.Q1&&!yc.Q2&&!yc.Q3&&!yc.Q4&&!yc.weeksPerQuarter){
    delete cal[yr];
  } else {
    cal[yr]=yc;
  }
  saveQuarterCalendarStore(cal);
  var status=document.getElementById('qcalStatus');
  if(status){
    status.textContent='✓ Saved TCP calendar for '+yr+'. Reloading data…';
    status.style.display='block';
  }
  // Re-render anything depending on weeks
  setTimeout(function(){
    try{if(typeof renderDash==='function')renderDash();}catch(e){}
    try{if(typeof renderRL==='function')renderRL();}catch(e){}
    try{if(typeof renderGoals==='function')renderGoals();}catch(e){}
    if(status){status.textContent='✓ Saved & applied. Switch tabs to see updated weeks.';}
  },200);
}
function clearQuarterCalendar(){
  var sel=document.getElementById('qcalYr');
  if(!sel)return;
  if(!confirm('Clear all TCP calendar overrides for '+sel.value+' and revert to default calendar quarters?'))return;
  var yr=String(sel.value);
  var cal=loadQuarterCalendarStore();
  delete cal[yr];
  saveQuarterCalendarStore(cal);
  renderQuarterCalendar();
  var status=document.getElementById('qcalStatus');
  if(status){
    status.textContent='✓ Cleared '+yr+' overrides. Using default calendar quarters.';
    status.style.display='block';
    setTimeout(function(){status.style.display='none';},3000);
  }
}
function copyQuarterCalendarFromPrev(){
  var sel=document.getElementById('qcalYr');
  if(!sel)return;
  var yr=parseInt(sel.value);
  var prevYr=String(yr-1);
  var cal=loadQuarterCalendarStore();
  var prev=cal[prevYr];
  if(!prev||(!prev.Q1&&!prev.Q2&&!prev.Q3&&!prev.Q4)){
    alert('No saved TCP calendar found for '+prevYr+'. Set up '+prevYr+' first, or enter '+yr+' dates manually.');
    return;
  }
  // Shift each Q's date by ~52 weeks (will adjust to same day-of-week)
  var newYc={};
  ['Q1','Q2','Q3','Q4'].forEach(function(q){
    if(prev[q]){
      var p=prev[q].split('-');
      var d=new Date(parseInt(p[0]),parseInt(p[1])-1,parseInt(p[2]));
      d.setDate(d.getDate()+364);
      newYc[q]=fmtYMD(d);
    }
  });
  if(prev.weeksPerQuarter)newYc.weeksPerQuarter=prev.weeksPerQuarter;
  cal[String(yr)]=newYc;
  saveQuarterCalendarStore(cal);
  renderQuarterCalendar();
  var status=document.getElementById('qcalStatus');
  if(status){
    status.textContent='✓ Copied from '+prevYr+' and shifted by 52 weeks. Review and adjust if needed.';
    status.style.display='block';
  }
}

