// ── Scoring weights ──────────────────────────────────────────────────────────
var DEFAULT_WEIGHTS = {revenue:50, calls:30, credits:10, art:5, hours:5};
var WEIGHT_STORE = 'salesTracker_weights';
var DEFAULT_THRESHOLDS = {
  revenue:{e5:110,e4:100,e3:85,e2:70},
  calls:  {e5:110,e4:100,e3:85,e2:70},
  hours:  {e5:110,e4:100,e3:85,e2:70},
  art:    {e5:1,  e4:2,  e3:4, e2:6},
  credits:{e5:0,  e4:1,  e3:3, e2:5}
};
var THRESH_STORE='salesTracker_thresholds';
function loadThresholds(){
  try{var t=localStorage.getItem(THRESH_STORE);if(t)return JSON.parse(t);}catch(e){}
  return JSON.parse(JSON.stringify(DEFAULT_THRESHOLDS));
}
function saveThresholds(obj){
  try{localStorage.setItem(THRESH_STORE,JSON.stringify(obj));}catch(e){}
}


function loadWeights(){
  try{
    var w = localStorage.getItem(WEIGHT_STORE);
    if(w) return JSON.parse(w);
  }catch(e){}
  return Object.assign({}, DEFAULT_WEIGHTS);
}

function getWeights(){ return loadWeights(); }

function saveWeights(){
  var inputs = document.querySelectorAll('.weight-input');
  var w = {};
  inputs.forEach(function(el){ w[el.dataset.key] = parseFloat(el.value)||0; });
  var total = Object.values(w).reduce(function(s,v){return s+v;},0);
  if(Math.abs(total-100)>0.1){
    alert('Weights must add up to 100%. Current total: '+total.toFixed(1)+'%');
    return;
  }
  try{ localStorage.setItem(WEIGHT_STORE, JSON.stringify(w)); }catch(e){}
  renderAdminWeights();
  // Refresh scoring displays
  if(document.getElementById('pg-lb').classList.contains('active')) renderLB();
  if(document.getElementById('pg-dash').classList.contains('active')) renderDash();
  var st = document.getElementById('saveStatus');
  if(st){st.textContent='Weights saved \u2713';st.style.color='#5DCAA5';}
  setTimeout(function(){if(st)st.textContent='';},2000);
}

function resetWeights(){
  if(!confirm('Reset scoring weights to defaults (Sales 50%, Calls 30%, Credits 10%, Art 5%, Hours 5%)?')) return;
  try{ localStorage.removeItem(WEIGHT_STORE); }catch(e){}
  renderAdminWeights();
}

var WEIGHT_DEFS = [
  {key:'revenue', label:'Sales revenue', icon:'💰', desc:'Primary revenue metric vs paced quarterly goal', color:'#FA873D'},
  {key:'calls',   label:'Call coverage', icon:'📞', desc:'Accounts called vs set size — pipeline activity', color:'#5DCAA5'},
  {key:'credits', label:'Rep-fault credits', icon:'🔄', desc:'Credit memos where rep was at fault — lower is better', color:'#EF9F27'},
  {key:'art',     label:'Art error rate', icon:'🎨', desc:'Art errors as % of total orders — lower is better', color:'#F09595'},
  {key:'hours',   label:'Hours worked', icon:'⏱', desc:'Hours worked vs weekly goal of 42.5 hrs', color:'#00AFEF'},
];

function renderAdminWeights(){
  var w = loadWeights();
  var grid = document.getElementById('weightGrid');
  if(!grid) return;
  grid.innerHTML = WEIGHT_DEFS.map(function(d){
    return '<div style="background:var(--color-background-secondary);border-radius:var(--border-radius-lg);padding:14px 16px;border:0.5px solid var(--color-border-secondary);">'
      +'<div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;">'
      +'<span style="font-size:18px;">'+d.icon+'</span>'
      +'<div><div style="font-size:12px;font-weight:500;">'+d.label+'</div>'
      +'<div style="font-size:10px;color:var(--color-text-secondary);">'+d.desc+'</div></div></div>'
      +'<div style="display:flex;align-items:center;gap:10px;">'
      +'<input type="range" class="weight-input" data-key="'+d.key+'" min="0" max="100" step="1" value="'+(w[d.key]||0)+'" oninput="updateWeightDisplay(this)" style="flex:1;accent-color:'+d.color+';">'
      +'<span class="weight-val" style="font-size:15px;font-weight:700;color:'+d.color+';min-width:44px;text-align:right;">'+(w[d.key]||0)+'%</span>'
      +'</div>'
      +'</div>';
  }).join('');
  updateWeightTotal();
}

function renderAdminThresholds(){
  var th=loadThresholds(),grid=document.getElementById('threshGrid');
  if(!grid)return;
  var defs=[
    {key:'revenue',label:'Sales revenue',icon:'&#128176;',col:'#FA873D',inv:false,desc:'% of quarterly revenue goal'},
    {key:'calls',label:'Call coverage',icon:'&#128222;',col:'#5DCAA5',inv:false,desc:'% of account set called'},
    {key:'hours',label:'Hours worked',icon:'&#9201;',col:'#00AFEF',inv:false,desc:'% of weekly hours goal'},
    {key:'art',label:'Art error rate',icon:'&#127912;',col:'#F09595',inv:true,desc:'error rate — lower is better'},
    {key:'credits',label:'Rep-fault credits',icon:'&#128260;',col:'#EF9F27',inv:true,desc:'% of revenue — lower is better'}
  ];
  grid.innerHTML=defs.map(function(d){
    var t=th[d.key]||DEFAULT_THRESHOLDS[d.key],sign=d.inv?'&le;':'&ge;';
    var lvls=[{k:'e5',lbl:'&#129351; Exceptional ('+sign+')',col:'#5DCAA5'},{k:'e4',lbl:'&#129352; Exceeds ('+sign+')',col:'#FA873D'},{k:'e3',lbl:'Meets ('+sign+')',col:'#EF9F27'},{k:'e2',lbl:'Not Meeting ('+sign+')',col:'#F09595'}];
    var inputs=lvls.map(function(lv){
      return'<div style="display:flex;align-items:center;gap:6px;margin-bottom:6px;"><div style="width:160px;font-size:10px;font-weight:500;color:'+lv.col+';">'+lv.lbl+'</div>'
        +'<input type="number" min="0" max="500" step="0.5" value="'+t[lv.k]+'" data-key="'+d.key+'" data-level="'+lv.k+'" class="thresh-input" style="width:64px;padding:4px 8px;background:var(--color-background-secondary);border:0.5px solid var(--color-border-secondary);border-radius:5px;color:var(--color-text-primary);font-size:12px;text-align:right;">'
        +'<span style="font-size:11px;color:var(--color-text-secondary);">%</span></div>';
    }).join('');
    return'<div style="background:var(--color-background-secondary);border-radius:var(--border-radius-lg);padding:14px 16px;border:0.5px solid var(--color-border-secondary);">'
      +'<div style="display:flex;align-items:center;gap:8px;margin-bottom:11px;"><span style="font-size:18px;">'+d.icon+'</span>'
      +'<div><div style="font-size:12px;font-weight:600;color:white;">'+d.label+'</div>'
      +'<div style="font-size:10px;color:var(--color-text-secondary);">'+d.desc+'</div></div></div>'
      +inputs+'<div style="margin-top:8px;padding:5px 8px;background:rgba(255,255,255,.03);border-radius:5px;font-size:9px;color:var(--color-text-secondary);">'
      +(d.inv?'Lower % = better. Score 5 if ≤ Exceptional.':'Higher % = better. Score 5 if ≥ Exceptional.')+'</div></div>';
  }).join('');
}
function applyThresholds(){
  var th={};document.querySelectorAll('.thresh-input').forEach(function(el){var k=el.dataset.key,lv=el.dataset.level;if(!th[k])th[k]={};th[k][lv]=parseFloat(el.value)||0;});
  var invKeys=['art','credits'],ok2=true,msg='';
  Object.keys(th).forEach(function(k){var t=th[k],inv=invKeys.indexOf(k)>=0;
    if(inv){if(!(t.e5<=t.e4&&t.e4<=t.e3&&t.e3<=t.e2)){ok2=false;msg='Art/credits: values must increase.';}} 
    else{if(!(t.e5>=t.e4&&t.e4>=t.e3&&t.e3>=t.e2)){ok2=false;msg='Revenue/calls/hours: values must decrease.';}}});
  var st=document.getElementById('threshStatus');
  if(!ok2){if(st)st.innerHTML='<span style="color:#F09595;">⚠ '+msg+'</span>';return;}
  saveThresholds(th);if(st){st.textContent='Saved ✓';st.style.color='#5DCAA5';}
  setTimeout(function(){if(st)st.textContent='';},2500);renderDash();
}
function resetThresholds(){
  saveThresholds(JSON.parse(JSON.stringify(DEFAULT_THRESHOLDS)));renderAdminThresholds();
  var st=document.getElementById('threshStatus');
  if(st){st.textContent='Reset ✓';st.style.color='#5DCAA5';}
  setTimeout(function(){if(st)st.textContent='';},2500);renderDash();
}

function updateWeightDisplay(el){
  var val = document.querySelector('.weight-val[data-key="'+el.dataset.key+'"]');
  // val is the sibling span
  el.nextElementSibling.textContent = el.value+'%';
  updateWeightTotal();
}

function updateWeightTotal(){
  var inputs = document.querySelectorAll('.weight-input');
  var total = 0;
  inputs.forEach(function(el){ total += parseFloat(el.value)||0; });
  var el = document.getElementById('weightTotal');
  var warn = document.getElementById('weightWarn');
  if(el){
    el.textContent = total.toFixed(0)+'%';
    el.style.color = Math.abs(total-100)<0.5 ? '#5DCAA5' : '#F09595';
  }
  if(warn) warn.style.display = Math.abs(total-100)>0.5 ? 'block' : 'none';
}

