  +'<div class="theme-preview-panel"><div class="theme-preview-title">Preview</div><div class="theme-preview-mini"><div>Revenue<strong>$3.5M</strong></div><div>Coverage<strong>74%</strong></div><div>Risk<strong>6</strong></div></div></div>';
  var st=document.getElementById('themeStatus'); if(st)st.textContent='Selected theme: '+getThemePreset(current.preset).name+'. Click Apply selected theme to save/apply it.';
