function parseCSVLine(line){var out=[],cur='',q=false; for(var i=0;i<line.length;i++){var c=line[i]; if(c==='"'){if(q&&line[i+1]==='"'){cur+='"';i++;}else q=!q;}else if(c===','&&!q){out.push(cur);cur='';}else cur+=c;} out.push(cur); return out;}
function parseProductionCSV(text){var lines=text.split(/\r?\n/).filter(function(x){return x.trim();}); if(!lines.length)return[]; var headers=parseCSVLine(lines[0]).map(function(h){return h.trim().toLowerCase();}); var decoIdx=headers.findIndex(function(h){return h.indexOf('decoration')>=0 || h.indexOf('method')>=0;}); var shipIdx=headers.findIndex(function(h){return h.indexOf('ship')>=0 || h.indexOf('date')>=0;}); var updIdx=headers.findIndex(function(h){return h.indexOf('updated')>=0;}); if(decoIdx<0)decoIdx=0; if(shipIdx<0)shipIdx=1; return lines.slice(1).map(function(line){var p=parseCSVLine(line); return {decoration:(p[decoIdx]||'').trim(),shipWeek:(p[shipIdx]||'').trim(),updated:(p[updIdx]||'').trim()};}).filter(function(r){return r.decoration||r.shipWeek;});}
function calcLeadDays(d){var dt=new Date(d); if(isNaN(dt))return null; var now=new Date(); now.setHours(0,0,0,0); dt.setHours(0,0,0,0); return Math.ceil((dt-now)/86400000);}
function renderProductionPreview(rows){var body=document.getElementById('productionPreviewBody'); if(!body)return; if(!rows||!rows.length){body.innerHTML='<tr><td colspan="4">No production rows found.</td></tr>';return;} body.innerHTML=rows.slice(0,20).map(function(r){var days=calcLeadDays(r.shipWeek); var status=days==null?'Unknown':days<=7?'Fast':days<=14?'Normal':'Extended'; return '<tr><td>'+esc_html(r.decoration)+'</td><td>'+esc_html(r.shipWeek)+'</td><td>'+(days==null?'—':days+' days')+'</td><td>'+status+'</td></tr>';}).join('');}
function refreshProductionFeed(){var cfg=getProductionFeedSettings(); var url=(document.getElementById('prodCsvUrlInput')||{}).value||cfg.url||''; var st=document.getElementById('productionFeedStatus'); if(!url){if(st)st.textContent='Paste a published Google Sheet CSV URL first.'; return;} if(st)st.textContent='Refreshing production feed…'; fetch(url).then(function(r){if(!r.ok)throw new Error('HTTP '+r.status); return r.text();}).then(function(t){var rows=parseProductionCSV(t); cfg.url=url; cfg.lastRefresh=new Date().toISOString(); cfg.rows=rows; cfg.includeInReports=!!(document.getElementById('prodInReports')||{}).checked; localStorage.setItem(PROD_FEED_STORE,JSON.stringify(cfg)); renderProductionPreview(rows); if(st)st.textContent='Connected — '+rows.length+' rows loaded. Last refresh '+new Date(cfg.lastRefresh).toLocaleString(); loadAdminHealth();}).catch(function(e){if(st)st.textContent='Connection failed: '+e.message;});}
