/* ===== Relocate production sections: deadline+intel -> Production Intelligence page; status -> Admin ===== */
function relocateProductionSections(){
  var ck=document.getElementById('pg-cknow');
  var dest=document.getElementById('prodintel-content');
  var admin=document.getElementById('pg-admin');
  if(!ck||!dest||!admin)return;
  function findSec(txt){
    var secs=ck.querySelectorAll('section.cknow-panel');
    for(var i=0;i<secs.length;i++){var k=secs[i].querySelector('.cknow-section-kicker');if(k&&k.textContent.trim().toLowerCase().indexOf(txt)>=0)return secs[i];}
    return null;
  }
  var prodStatus=findSec('live production status');
  var prodIntel=findSec('production intelligence');
  var deadline=findSec('deadline calculator');
  if(deadline)deadline.remove();
  if(prodIntel)dest.appendChild(prodIntel);
  if(prodStatus)admin.appendChild(prodStatus);
}
window.addEventListener('load',function(){try{relocateProductionSections();}catch(e){}});
var DEADLINE_ART_STORE='salesTracker_deadlineArt_v1';
function loadDeadlineArt(){try{return JSON.parse(localStorage.getItem(DEADLINE_ART_STORE))||{};}catch(e){return {};}}
function saveDeadlineArtStore(o){try{localStorage.setItem(DEADLINE_ART_STORE,JSON.stringify(o));}catch(e){}}
function _dlEsc(s){return String(s).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;');}
function renderDeadlineArtConfig(){
  var grid=document.getElementById('deadlineArtGrid');if(!grid)return;
  var rows=(typeof getProductionRows==='function')?getProductionRows():[];
  var store=loadDeadlineArt();
  if(!rows||!rows.length){grid.innerHTML='<div style="font-size:12px;color:var(--color-text-secondary);">No deco methods found yet \u2014 load the Production Status Center first.</div>';return;}
  grid.innerHTML=rows.map(function(r){
    var d=r.decoration||''; var v=store[d]||{};
    function inp(k,lbl){return '<div style="display:flex;flex-direction:column;gap:2px;"><label style="font-size:10px;color:var(--color-text-secondary);">'+lbl+'</label><input type="number" min="0" data-deco="'+_dlEsc(d)+'" data-key="'+k+'" value="'+(v[k]!=null?v[k]:'')+'" style="width:62px;background:var(--color-background-secondary);border:0.5px solid var(--color-border-secondary);color:var(--color-text-primary);padding:5px 7px;border-radius:5px;font-size:12px;"></div>';}
    return '<div style="background:rgba(250,135,61,.05);border:0.5px solid rgba(250,135,61,.25);border-radius:8px;padding:10px 12px;margin-bottom:8px;">'
      +'<div style="font-size:12px;font-weight:600;color:var(--color-text-primary);margin-bottom:6px;">'+_dlEsc(d)+'</div>'
      +'<div style="display:flex;gap:10px;flex-wrap:wrap;">'+inp('nn','New / New')+inp('rn','Repeat / New')+inp('rr','Repeat / Repeat')+'</div></div>';
  }).join('');
}
function saveDeadlineArtConfig(){
  var grid=document.getElementById('deadlineArtGrid');if(!grid)return;
  var store={};
  grid.querySelectorAll('input[data-deco]').forEach(function(i){
    var d=i.getAttribute('data-deco'),k=i.getAttribute('data-key'),val=(i.value||'').trim();
    if(!store[d])store[d]={};
    if(val!=='')store[d][k]=parseInt(val,10)||0;
  });
  saveDeadlineArtStore(store);
  var s=document.getElementById('deadlineArtSaved');if(s){s.textContent='Saved \u2713';setTimeout(function(){s.textContent='';},2000);}
}
/* ===== TCP Deadline calculator: order form (piece 2) ===== */
function _dlDecoMethodOptions(){
  var rows=(typeof getProductionRows==='function')?getProductionRows():[];
  if(!rows||!rows.length)return '<option value="">(load Production Status Center)</option>';
  return rows.map(function(r){return '<option value="'+_dlEsc(r.decoration)+'">'+_dlEsc(r.decoration)+'</option>';}).join('');
}
function addDeadlineDeco(){
  var box=document.getElementById('dlDecoBlocks');if(!box)return;
  var div=document.createElement('div');div.className='dl-deco-block';
  div.style.cssText='border:0.5px solid var(--color-border-secondary);border-radius:10px;padding:10px 12px;margin-bottom:8px;';
  div.innerHTML='<div class="ig"><label>Deco method</label><select class="dl-deco">'+_dlDecoMethodOptions()+'</select></div>'+
    '<div class="ig"><label>Art status</label><select class="dl-art"><option value="nn">New / New</option><option value="rn">Repeat / New</option><option value="rr">Repeat / Repeat</option></select></div>'+
    '<label style="display:flex;align-items:center;gap:6px;font-size:12px;margin:8px 0 4px;"><input type="checkbox" class="dl-mock"> Mockup needed</label>'+
    '<button type="button" onclick="this.closest(&quot;.dl-deco-block&quot;).remove()" style="background:none;border:none;color:#F09595;font-size:11px;cursor:pointer;padding:0;">Remove</button>';
  box.appendChild(div);
}
function readDeadlineForm(){
  var blocks=[].slice.call(document.querySelectorAll('#dlDecoBlocks .dl-deco-block')).map(function(b){
    return {deco:(b.querySelector('.dl-deco')||{}).value||'',art:(b.querySelector('.dl-art')||{}).value||'nn',mockup:!!(b.querySelector('.dl-mock')||{}).checked};
  });
  return {decos:blocks,
    garmentDate:(document.getElementById('dlGarmentDate')||{}).value||'',
    inHands:(document.getElementById('dlInHands')||{}).value||'',
    zip:((document.getElementById('dlZip')||{}).value||'').trim()};
}
async function calculateDeadline(){
  var rEl=document.getElementById('dlResult');if(!rEl)return;
  var f=readDeadlineForm();
  if(!f.decos.length){rEl.className='cutoff-result warn';rEl.textContent='Add at least one deco method first.';return;}
  if(!f.garmentDate||!f.inHands||!f.zip){rEl.className='cutoff-result warn';rEl.textContent='Fill in garment arrival, in-hands date, and ship-to ZIP.';return;}
  rEl.className='cutoff-result';rEl.textContent='Calculating... estimating UPS Ground transit...';
  var rows=(typeof getProductionRows==='function')?getProductionRows():[];
  var art=loadDeadlineArt();
  var prodDays=0,artDays=0,missingProd=[],missingArt=[];
  f.decos.forEach(function(d){
    var row=rows.find(function(r){return r.decoration===d.deco;});
    var ld=row?leadDaysFromToday(row.shipWeek):null;
    if(typeof ld==='number'&&!isNaN(ld))prodDays+=Math.max(0,ld); else missingProd.push(d.deco||'(none)');
    var a=(art[d.deco]||{})[d.art];
    if(typeof a==='number')artDays+=a; else missingArt.push(d.deco||'(none)');
  });
  var transit=null;
  try{
    var resp=await callAI('Estimate UPS Ground transit time in BUSINESS DAYS from ZIP 53185 (Waterford, Wisconsin) to ZIP '+f.zip+'. Reply with ONLY a single integer, nothing else.',{maxTokens:60,skipCompanyContext:true});
    var mn=String(resp).match(/\d+/); if(mn)transit=parseInt(mn[0],10);
  }catch(e){transit=null;}
  function addProd(startStr,n){var d=new Date(startStr+'T00:00:00');var a=0;while(a<n){d.setDate(d.getDate()+1);var w=d.getDay();if(w>=1&&w<=4)a++;}return d;}
  function addBiz(dObj,n){var d=new Date(dObj);var a=0;while(a<n){d.setDate(d.getDate()+1);var w=d.getDay();if(w>=1&&w<=5)a++;}return d;}
  function subBiz(startStr,n){var d=new Date(startStr+'T00:00:00');var s=0;while(s<n){d.setDate(d.getDate()-1);var w=d.getDay();if(w>=1&&w<=5)s++;}return d;}
  function cntMonThu(a,b){var d=new Date(a);var c=0;while(d<b){d.setDate(d.getDate()+1);var w=d.getDay();if(w>=1&&w<=4)c++;}return c;}
  function fmtD(d){return d.toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric',year:'numeric'});}
  var canShip=addProd(f.garmentDate,prodDays);
  var inHandsD=new Date(f.inHands+'T00:00:00');
  var shipBy=(transit!=null)?subBiz(f.inHands,transit):null;
  var arrives=(transit!=null)?addBiz(canShip,transit):null;
  var win=(shipBy!=null)?cntMonThu(new Date(f.garmentDate+'T00:00:00'),shipBy):null;
  var flags=[],severe=false;
  if(win!=null){
    if(win<prodDays){flags.push('&#9888; Manager approval needed &mdash; production needs '+prodDays+' working days but only '+win+' fit before the ground ship-by date.');severe=true;}
    if(win<=5&&win<prodDays){flags.push('&#9888; Super rush needed &mdash; 5 or fewer working days available.');severe=true;}
  }
  var expedite=false;
  if(arrives!=null&&arrives>inHandsD){expedite=true;severe=true;flags.push('&#9888; Expedite shipping needed &mdash; ground would arrive '+fmtD(arrives)+', after the in-hands date of '+fmtD(inHandsD)+'.');}
  var html='<div style="font-weight:700;margin-bottom:6px;">We can ship on '+fmtD(canShip)+'</div>';
  html+='<div>Production: '+prodDays+' working days (Mon-Thu) from garment arrival'+(missingProd.length?' <span style="color:#FFD27A;">&mdash; no lead time for: '+missingProd.join(', ')+'</span>':'')+'</div>';
  html+='<div>Art (info): '+artDays+' days'+(missingArt.length?' <span style="color:#FFD27A;">(set art days for: '+missingArt.join(', ')+')</span>':'')+'</div>';
  if(transit!=null){html+='<div>UPS Ground transit (AI est.): '+transit+' business days &rarr; arrives ~'+fmtD(arrives)+'</div><div>Ground ship-by to hit in-hands: '+(shipBy?fmtD(shipBy):'-')+'</div>';}
  else html+='<div style="color:#FFD27A;">Could not estimate transit (check the API key and ZIP).</div>';
  html+=flags.length?'<div style="margin-top:8px;">'+flags.join('<br>')+'</div>':'<div style="margin-top:8px;color:#A7FFC0;">On track for the in-hands date.</div>';
  rEl.className='cutoff-result'+(flags.length?(severe?' bad':' warn'):' good');
  rEl.innerHTML=html;
}

