/* ===== TCP v273 Meeting Report PDF Print Overhaul =====
   Purpose: rebuild the printable meeting packet styling so it is brand-aligned,
   readable, and print friendly without changing the meeting-report data logic. */
function buildReportCSSPrint(){
  return `:root{--tcp-navy:#111B2E;--tcp-blue:#008CC0;--tcp-cyan:#06B6D4;--tcp-orange:#F97316;--tcp-gold:#F59E0B;--tcp-green:#059669;--tcp-red:#DC2626;--tcp-purple:#FA873D;--ink:#151515;--muted:#667085;--soft:#F8FAFC;--line:#E4E7EC;--line2:#EAECF0;--panel:#FFFFFF;--shade:#F2F4F7;}
*{box-sizing:border-box;margin:0;padding:0;}
html,body{background:#E9EDF5;color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Arial,sans-serif;font-size:10.6px;line-height:1.34;-webkit-print-color-adjust:exact;print-color-adjust:exact;}
.report-shell{width:8.5in;max-width:100%;margin:0 auto;background:#fff;box-shadow:0 18px 55px rgba(15,23,42,.12);min-height:100vh;}
.report-header{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;padding:18px 22px 16px;background:linear-gradient(135deg,#0E172A 0%,#17284B 58%,#0E5663 100%);color:#fff;border-bottom:4px solid var(--tcp-orange);}
.rh-left{display:flex;align-items:center;gap:12px;min-width:0}.rh-left img{width:36px;height:36px;object-fit:contain}.rh-coname{font-size:16px;font-weight:900;letter-spacing:-.02em}.rh-cosub{font-size:9px;color:rgba(255,255,255,.68);margin-top:2px}.rh-right{text-align:right;min-width:190px}.rh-type{font-size:9px;text-transform:uppercase;letter-spacing:.14em;font-weight:900;color:#A7F3D0}.rh-title{font-size:20px;font-weight:950;letter-spacing:-.04em;line-height:1.05;margin-top:3px}.rh-date{font-size:9.5px;color:rgba(255,255,255,.70);margin-top:5px}
.report-body{padding:14px 20px 16px;background:#fff;}
.report-footer{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:9px 20px 10px;border-top:1px solid var(--line);font-size:8.5px;color:#98A2B3;background:#FCFCFD;}
.kpi-strip{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:7px;margin:0 0 10px;page-break-inside:avoid;break-inside:avoid;}
.kpi-cell,.fc-card,.fcard{background:linear-gradient(180deg,#fff 0%,#F8FAFC 100%);border:1px solid #E6EAF0;border-radius:10px;padding:9px 10px;box-shadow:0 4px 10px rgba(15,23,42,.035);page-break-inside:avoid;break-inside:avoid;}
.kl,.fc-label,.fcard-lbl{font-size:7.8px;font-weight:950;text-transform:uppercase;letter-spacing:.08em;color:#667085;margin-bottom:4px;white-space:nowrap}.kv,.fc-val,.fcard-val{font-size:17px;font-weight:950;color:#151515;line-height:1.05;letter-spacing:-.035em}.ks,.fc-sub,.fcard-sub{font-size:8.4px;color:#667085;margin-top:4px}.fc-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.fc-bar,.bar{height:5px;background:#EEF2F6;border-radius:999px;overflow:hidden;margin-top:7px}.fc-fill,.bar-fill{height:100%;border-radius:999px}.bar{width:58px;display:inline-block;vertical-align:middle;margin:0;}
.section{background:#fff;border:1px solid var(--line);border-radius:12px;padding:10px 12px;margin:0 0 10px;page-break-inside:auto;break-inside:auto;}.section.compact{padding:9px 10px}.keep-together,.fc-card,.rep-card,.ai-card,.intel-card,.fcard{page-break-inside:avoid;break-inside:avoid;}.page-break-after{page-break-after:auto!important;break-after:auto!important;}
.sec-title{font-size:9px;font-weight:950;color:#344054;text-transform:uppercase;letter-spacing:.08em;margin-bottom:8px;display:flex;align-items:center;gap:7px;padding-bottom:7px;border-bottom:1px solid #EEF2F6;}.sec-title::after{content:'';height:1px;background:#F2F4F7;flex:1;}
.rep-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:7px}.rep-card{border:1px solid #E6EAF0;border-radius:11px;background:#fff;padding:8px 9px;display:flex;gap:8px;align-items:flex-start;min-height:78px;box-shadow:0 3px 8px rgba(15,23,42,.03)}.rep-card.gold{border-color:#FDE68A;background:#FFFBEB}.rep-card.silver{border-color:#E5E7EB;background:#F9FAFB}.rep-card.bronze{border-color:#FED7AA;background:#FFF7ED}.rep-av,.av{width:30px;height:30px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:9px;font-weight:950;flex-shrink:0;object-fit:cover}.rep-medal{font-size:9px;color:#667085;font-weight:900}.rep-name{font-size:10px;font-weight:950;color:#151515;line-height:1.1}.rep-stats,.rep-pct{font-size:8.2px;color:#667085;line-height:1.25}.rep-rev{font-size:14px;font-weight:950;color:#151515;margin-top:3px;letter-spacing:-.03em}
.data-tbl,.data-table,.evt-tbl{width:100%;border-collapse:separate;border-spacing:0;font-size:9.2px;border:1px solid #E6EAF0;border-radius:9px;overflow:hidden;table-layout:fixed}.data-tbl th,.data-table th,.evt-tbl th{background:#F2F4F7;color:#475467;padding:5px 6px;text-align:left;font-weight:950;font-size:7.8px;text-transform:uppercase;letter-spacing:.04em;border-bottom:1px solid #D0D5DD}.data-tbl td,.data-table td,.evt-tbl td{padding:4.7px 6px;border-bottom:1px solid #EEF2F6;vertical-align:middle;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.data-tbl tr:nth-child(even) td,.data-table tr:nth-child(even) td,.evt-tbl tr:nth-child(even) td{background:#FAFAFB}.data-tbl tr:last-child td,.data-table tr:last-child td,.evt-tbl tr:last-child td{border-bottom:none}.data-tbl th:nth-child(1),.data-tbl td:nth-child(1){width:23%}.data-tbl th:last-child,.data-tbl td:last-child{width:11%}.r{text-align:right!important}.ai-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.ai-card{border-radius:11px;border:1px solid #E6EAF0;padding:10px;min-height:72px}.ai-label{font-size:8px;font-weight:950;text-transform:uppercase;letter-spacing:.08em;margin-bottom:6px}.ai-body{font-size:9.3px;color:#344054;line-height:1.42}.intel-grid,.focus-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.intel-card{border-radius:11px;border:1px solid #E6EAF0;background:#fff;padding:10px 11px;box-shadow:0 3px 8px rgba(15,23,42,.03)}.ic-title{font-size:10px;font-weight:950;color:#151515;margin-bottom:4px}.ic-body{font-size:9.5px;color:#344054;line-height:1.45}.pill{display:inline-block;font-size:7.5px;font-weight:900;padding:2px 6px;border-radius:999px;margin-left:4px;text-transform:uppercase;letter-spacing:.04em}.quote-box{border-left:3px solid var(--tcp-purple);background:#F4F3FF;border-radius:0 8px 8px 0;padding:7px 9px;margin-top:7px;font-size:9px;color:#344054;font-style:italic}.pitch{background:#FFFFFF!important;border-color:#C7D2FE!important}.no-print{display:inline-block}.print-note{display:none}.force-page{page-break-before:always!important;break-before:page!important;}.avoid-break{break-inside:avoid;page-break-inside:avoid;}
@page{size:letter;margin:.45in .42in;}@media print{html,body{background:#fff!important;padding:0!important}.report-shell{width:auto;max-width:none;margin:0;box-shadow:none;min-height:0}.report-body{padding:12px 0 0}.report-header{margin:0 0 12px;padding:15px 17px 13px;border-radius:0}.report-footer{padding:8px 0 0;margin-top:8px}.no-print{display:none!important}.print-note{display:block}.section{margin-bottom:9px}.kpi-strip{gap:6px}.rep-grid{gap:6px}.rep-card{min-height:72px;padding:7px 8px}.data-tbl td,.data-table td,.evt-tbl td{padding-top:4.3px;padding-bottom:4.3px}thead{display:table-header-group}tr{page-break-inside:avoid;break-inside:avoid}.force-page{page-break-before:always!important;break-before:page!important;}.section:has(.rep-grid){break-inside:avoid;page-break-inside:avoid}}`;
}

function buildReportPrint(title,sub,badgeText,bHtml){
  var ds=new Date().toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'});
  var wk=(String(sub||'').split('·')[0]||'').trim();
  var cleanHtml=String(bHtml||'')
    .replace(/page-break-after/g,'')
    .replace('&#128222; Customers Called','<span class="print-note"></span>&#128222; Customers Called')
    .replace('<div class="section"><div class="sec-title"><span style="display:flex;align-items:center;gap:5px;">&#128222; Customers Called','<div class="section force-page"><div class="sec-title"><span style="display:flex;align-items:center;gap:5px;">&#128222; Customers Called')
    .replace('<div class="section "><div class="sec-title"><span style="display:flex;align-items:center;gap:5px;">&#128222; Customers Called','<div class="section force-page"><div class="sec-title"><span style="display:flex;align-items:center;gap:5px;">&#128222; Customers Called');
  var logoSrc='data:image/png;base64,'+(typeof TCP_LOGO_B64!=='undefined'?TCP_LOGO_B64:'');
  return '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><title>'+String(title||'Weekly Sales Meeting').replace(/</g,'&lt;')+'</title><style>'+buildReportCSSPrint()+'</style></head><body>'+
    '<div class="report-shell">'+
      '<div class="report-header">'+
        '<div class="rh-left"><img src="'+logoSrc+'" alt="TCP"><div><div class="rh-coname">Triple Crown Products</div><div class="rh-cosub">triplecrownproducts.com &middot; Mukwonago, WI</div></div></div>'+
        '<div class="rh-right"><div class="rh-type">Weekly Sales Meeting</div><div class="rh-title">'+String(wk||badgeText||'Q2 2026').replace(/</g,'&lt;')+'</div><div class="rh-date">'+ds+'</div><button class="no-print" onclick="window.print()" style="margin-top:8px;padding:6px 12px;background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.28);color:white;border-radius:999px;font-size:10px;font-weight:800;cursor:pointer;">Save PDF</button></div>'+
      '</div>'+
      '<div class="report-body">'+cleanHtml+'</div>'+ 
      '<div class="report-footer"><span>Triple Crown Products &middot; Confidential</span><span>'+ds+'</span></div>'+ 
    '</div></body></html>';
}


// ===== v278 Reports Builder helpers (safe wrappers around existing report functions) =====
let _reportsSelectedType = 'rep';
function reportsSetType(type){
  _reportsSelectedType = type || 'rep';
  document.querySelectorAll('.reports-v278-type-card').forEach(function(btn){
    btn.classList.toggle('active', btn.getAttribute('data-report-type') === _reportsSelectedType);
  });
  var pill = document.getElementById('reportsTypePill');
  var help = document.getElementById('reportsGenerateHelp');
  var btn = document.getElementById('reportsMainGenerateBtn');
  var status = document.getElementById('reportsBuilderStatus');
  var repBrief = document.querySelectorAll('.reports-rep-scope');
  var repPdf = document.querySelectorAll('.reports-rep-output');
  var cfg = {
    meeting: {label:'Weekly Meeting Packet', help:'Open the weekly sales meeting packet for the selected week/quarter.', btn:'🚀 Build Meeting Packet', status:'Meeting packet selected'},
    rep: {label:'Rep Performance Packet', help:'Generate a PDF packet for the selected rep.', btn:'🚀 Generate Rep Packet', status:'Rep packet selected'},
    team: {label:'Team Leadership Report', help:'Generate a full team leadership report.', btn:'🚀 Generate Team Report', status:'Team report selected'}
  }[_reportsSelectedType] || {label:'Rep Performance Packet', help:'Generate a PDF packet for the selected rep.', btn:'🚀 Generate Rep Packet', status:'Rep packet selected'};
  if(pill) pill.textContent = cfg.label;
  if(help) help.textContent = cfg.help;
  if(btn) btn.textContent = cfg.btn;
  if(status) status.textContent = cfg.status;
  repBrief.forEach(function(el){ el.style.display = (_reportsSelectedType==='brief') ? '' : 'none'; });
  repPdf.forEach(function(el){ el.style.display = (_reportsSelectedType==='rep') ? '' : 'none'; });
  var hint = document.getElementById('reportsOutputHint');
  if(hint) hint.textContent = _reportsSelectedType==='rep' ? 'Quick view appears here; full packet via the button.' : 'PDF/print view opens in a new tab.';
}
function reportsRunSelected(){
  try{
    if(_reportsSelectedType === 'meeting' && typeof generateMeetingReport === 'function') return generateMeetingReport();
    if(_reportsSelectedType === 'rep' && typeof genRepPDF === 'function') return genRepPDF();
    if(_reportsSelectedType === 'team' && typeof genTeamPDF === 'function') return genTeamPDF();
  }catch(e){
    var out=document.getElementById('aiOut');
    if(out) out.innerHTML='<div class="aib">Report generation error: '+esc(e.message||e)+'</div>';
    console.error('Reports builder error:',e);
  }
}
window.addEventListener('load', function(){
  setTimeout(function(){ if(document.getElementById('pg-reports')) reportsSetType(_reportsSelectedType); }, 0);
});
